  --_mono-accordion-body-font-preset: var(--mono-accordion-body-font-sm, var(--mono-text-xs));
  --_mono-accordion-body-line-height-preset: var(--mono-text-xs--lh);
  --_mono-accordion-arrow-size-preset: calc(var(--mono-spacing) * 3.5);
  --_mono-accordion-glyph-size-preset: calc(var(--mono-spacing) * 6);
}
[mono-accordion][mono-size="lg"] {
  --_mono-accordion-pad-x-preset: var(--mono-accordion-pad-x-lg, calc(var(--mono-spacing) * 5));
  --_mono-accordion-pad-y-preset: var(--mono-accordion-pad-y-lg, calc(var(--mono-spacing) * 5));
  --_mono-accordion-radius-preset: var(--mono-accordion-radius-lg, var(--mono-radius-lg));
  --_mono-accordion-gap-preset: calc(var(--mono-spacing) * 3.5);
  --_mono-accordion-title-font-preset: var(--mono-accordion-title-font-lg, var(--mono-text-base));
  --_mono-accordion-title-line-height-preset: var(--mono-text-base--lh);
  --_mono-accordion-body-font-preset: var(--mono-accordion-body-font-lg, var(--mono-text-sm));
  --_mono-accordion-arrow-size-preset: calc(var(--mono-spacing) * 5);
  --_mono-accordion-glyph-size-preset: calc(var(--mono-spacing) * 8);
  --_mono-accordion-glyph-radius-preset: var(--mono-radius-md);
}
[mono-accordion][mono-size="xl"] {
  --_mono-accordion-pad-x-preset: var(--mono-accordion-pad-x-xl, calc(var(--mono-spacing) * 6));
  --_mono-accordion-pad-y-preset: var(--mono-accordion-pad-y-xl, calc(var(--mono-spacing) * 6));
  --_mono-accordion-radius-preset: var(--mono-accordion-radius-xl, var(--mono-radius-xl));
  --_mono-accordion-gap-preset: calc(var(--mono-spacing) * 4);
  --_mono-accordion-title-font-preset: var(--mono-accordion-title-font-xl, var(--mono-text-lg));
  --_mono-accordion-title-line-height-preset: var(--mono-text-lg--lh);
  --_mono-accordion-description-font-preset: var(--mono-text-sm);
  --_mono-accordion-body-font-preset: var(--mono-accordion-body-font-xl, var(--mono-text-base));
  --_mono-accordion-body-line-height-preset: var(--mono-text-base--lh);
  --_mono-accordion-arrow-size-preset: calc(var(--mono-spacing) * 5.5);
  --_mono-accordion-glyph-size-preset: calc(var(--mono-spacing) * 9);
  --_mono-accordion-glyph-radius-preset: var(--mono-radius-lg);
}
[mono-accordion][mono-size="xxl"] {
  --_mono-accordion-pad-x-preset: var(--mono-accordion-pad-x-xxl, calc(var(--mono-spacing) * 7));
  --_mono-accordion-pad-y-preset: var(--mono-accordion-pad-y-xxl, calc(var(--mono-spacing) * 7));
  --_mono-accordion-radius-preset: var(--mono-accordion-radius-xxl, var(--mono-radius-xl));
  --_mono-accordion-gap-preset: calc(var(--mono-spacing) * 4.5);
  --_mono-accordion-title-font-preset: var(--mono-accordion-title-font-xxl, var(--mono-text-xl));
  --_mono-accordion-title-line-height-preset: var(--mono-text-xl--lh);
  --_mono-accordion-description-font-preset: var(--mono-text-sm);
  --_mono-accordion-body-font-preset: var(--mono-accordion-body-font-xxl, var(--mono-text-lg));
  --_mono-accordion-body-line-height-preset: var(--mono-text-lg--lh);
  --_mono-accordion-arrow-size-preset: calc(var(--mono-spacing) * 6);
  --_mono-accordion-glyph-size-preset: calc(var(--mono-spacing) * 10);
  --_mono-accordion-glyph-radius-preset: var(--mono-radius-lg);
}
/* =========================================
   Colours — EXTENSION: the role tints the chevron, the ring and the open edge
   ========================================= */
[mono-accordion][mono-color="primary"] { --_mono-accordion-accent-preset: var(--_mono-accordion-primary); }
[mono-accordion][mono-color="secondary"] { --_mono-accordion-accent-preset: var(--_mono-accordion-secondary); }
[mono-accordion][mono-color="success"] { --_mono-accordion-accent-preset: var(--_mono-accordion-success); }
[mono-accordion][mono-color="danger"] { --_mono-accordion-accent-preset: var(--_mono-accordion-danger); }
[mono-accordion][mono-color="warning"] { --_mono-accordion-accent-preset: var(--_mono-accordion-warning); }
[mono-accordion][mono-color="info"] { --_mono-accordion-accent-preset: var(--_mono-accordion-info); }
[mono-accordion][mono-color="teal"] { --_mono-accordion-accent-preset: var(--_mono-accordion-teal); }
[mono-accordion][mono-color="purple"] { --_mono-accordion-accent-preset: var(--_mono-accordion-purple); }
[mono-accordion][mono-color="neutral"] { --_mono-accordion-accent-preset: var(--_mono-accordion-neutral); }
[mono-accordion][mono-color="dark"] { --_mono-accordion-accent-preset: var(--_mono-accordion-dark); }
/* =========================================
   States
   ========================================= */
[mono-accordion][mono-open] {
  border-color: var(--_mono-accordion-open-border-color);
  box-shadow: var(--_mono-accordion-open-shadow);
  background: var(--_mono-accordion-open-bg);
}
/* In a group the item has no frame to tint — only the open wash survives. */
:where([mono-accordion-group], .mono-accordion-group) > [mono-accordion][mono-open],
[mono-accordion][mono-grouped][mono-open] {
  border-color: var(--_mono-accordion-border);
  box-shadow: none;
}
/* basecoat@1.0.2 components/accordion.css .accordion > details[aria-disabled='true'] > summary, .accordion > details > summary[aria-disabled='true']
   — pointer-events-none opacity-50. DEVIATION: 0.6, this component's pre-port
   value, and on the whole item rather than the summary alone (the body is
   equally unusable). */
[mono-accordion][mono-disabled] {
  opacity: 0.6;
  pointer-events: none;
  cursor: not-allowed;
}
/* =========================================
   Head — `> summary`
   ========================================= */
/* basecoat@1.0.2 components/accordion.css .accordion > details > summary —
   relative flex w-full flex-1 cursor-pointer list-none items-start
   justify-between border border-transparent transition-all outline-none */
/* basecoat@1.0.2 styles/vega.css .accordion > details > summary — rounded-md py-4
   text-left text-sm font-medium hover:underline focus-visible:ring-3
   focus-visible:ring-ring/50 focus-visible:border-ring
   — DEVIATIONS: a real <button> (so it needs the UA button reset), and
   `items-center` rather than `items-start`: this row can carry a glyph chip and
   trailing actions, which upstream's text-only summary never does. */
:where([mono-accordion]) > [mono-head] {
  position: relative;
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--_mono-accordion-gap);
  padding: var(--_mono-accordion-pad-y) var(--_mono-accordion-pad-x);
  border: var(--mono-border-width) solid transparent;
  border-radius: var(--_mono-accordion-radius);
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  user-select: none;
  outline: none;
  appearance: none;
  box-shadow: var(--_mono-accordion-ring);
  transition:
    background-color var(--mono-duration) var(--mono-ease),
    border-color var(--mono-duration) var(--mono-ease),
    box-shadow var(--mono-duration) var(--mono-ease);
}
[mono-accordion] > [mono-head]:focus-visible {
  border-color: var(--_mono-accordion-ring-color);
  --_mono-accordion-ring: 0 0 0 var(--_mono-accordion-ring-width)
    color-mix(in oklab, var(--_mono-accordion-ring-color) var(--mono-ring-alpha), transparent);
}
/* `hover:underline` — on the label, which is the only text in upstream's summary. */
@media (hover: hover) {
  [mono-accordion] > [mono-head]:hover:not(:disabled) {
    background: var(--_mono-accordion-head-hover-bg);
  }

  [mono-accordion] > [mono-head]:hover:not(:disabled) [mono-title] {
    text-decoration-line: var(--_mono-accordion-title-hover-decoration);
  }
}
[mono-accordion] > [mono-head]:disabled {
  pointer-events: none;
  cursor: not-allowed;
}
/* =========================================
   Leading chip — EXTENSION
   ========================================= */
:where([mono-accordion] > [mono-head]) > [mono-glyph] {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_mono-accordion-glyph-size);
  height: var(--_mono-accordion-glyph-size);
  border-radius: var(--_mono-accordion-glyph-radius);
  background: var(--_mono-accordion-glyph-bg);
  color: var(--_mono-accordion-glyph-color);
  line-height: 1;
}
/* The glyph itself fills the chip at 62% — light: the `[data-mono-slot]`
   placeholder the svg is moved into; shadow: the projected svg. */
[mono-accordion] > [mono-head] > [mono-glyph] > [data-mono-slot="icon"],
[mono-accordion] > [mono-head] > [mono-glyph] > svg,
[mono-accordion] > [mono-head] > [mono-glyph] slot[name="icon"]::slotted(svg) {
  display: block;
  width: 62%;
  height: 62%;
}
/* …and the light build's svg fills that placeholder. It used to lean on a global
   `[data-mono-slot='icon'] > svg` rule in chip.css; since the Basecoat port that
   rule is scoped to chips, and an unsized inline svg falls back to 300×150. */
[mono-accordion] > [mono-head] > [mono-glyph] > [data-mono-slot="icon"] > svg {
  display: block;
  width: 100%;
  height: 100%;
}
/* =========================================
   Title + description
   ========================================= */
:where([mono-accordion] > [mono-head]) > [mono-heading] {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--mono-spacing) * 0.25);
}
/* `> slot[name="header"]`: in the shadow build the title/subtitle are the
   FALLBACK content of `<slot name="header">`, so they sit one element deeper. */
:where(
  [mono-accordion] > [mono-head] > [mono-heading],
  [mono-accordion] > [mono-head] > [mono-heading] > slot[name="header"]
) > [mono-title] {
  font-size: var(--_mono-accordion-title-font);
  line-height: var(--_mono-accordion-title-line-height);
  font-weight: var(--_mono-accordion-title-weight);
  color: var(--_mono-accordion-text);
}
:where(
  [mono-accordion] > [mono-head] > [mono-heading],
  [mono-accordion] > [mono-head] > [mono-heading] > slot[name="header"]
) > :is([mono-subtitle], [mono-description]) {
  font-size: var(--_mono-accordion-description-font);
  line-height: var(--mono-leading-normal);
  color: var(--_mono-accordion-description-color);
}
:where([mono-accordion] > [mono-head]) > [mono-actions] {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: calc(var(--mono-spacing) * 1.5);
}
/* =========================================
   Chevron — `summary > svg:last-child`
   ========================================= */
/* basecoat@1.0.2 styles/vega.css .accordion > details > summary > svg:last-child
   — text-muted-foreground ms-auto size-4 */
/* basecoat@1.0.2 components/accordion.css .accordion > details > summary > svg:last-child
   — pointer-events-none shrink-0 transition-transform */
:where([mono-accordion] > [mono-head]) > [mono-arrow] {
  flex-shrink: 0;
  margin-inline-start: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_mono-accordion-arrow-size);
  height: var(--_mono-accordion-arrow-size);
  color: var(--_mono-accordion-arrow-color);
  pointer-events: none;
  transition:
    rotate var(--_mono-accordion-duration) var(--mono-ease),
    color var(--mono-duration) var(--mono-ease);
}
[mono-accordion] > [mono-head] > [mono-arrow] > :is(svg, span) {
  display: block;
  width: 100%;
  height: 100%;
}
/* basecoat@1.0.2 components/accordion.css .accordion > details[open] > summary > svg:last-child
   — rotate-180 */
[mono-accordion][mono-open] > [mono-head] > [mono-arrow] {
  rotate: 180deg;
  color: var(--_mono-accordion-arrow-open-color);
}
/* =========================================
   Body — `details > :not(summary)`
   ========================================= */
/* basecoat@1.0.2 components/accordion.css .accordion > details > :not(summary) — overflow-hidden */
/* basecoat@1.0.2 styles/vega.css .accordion > details > :not(summary) — pt-0 pb-4 text-sm
   A <details> collapses for free; a div has to be animated. The
   `grid-template-rows: 0fr → 1fr` trick measures the content's natural height
   through the grid track and interpolates the row size, with the vertical padding
   and the top border collapsing in lockstep so the entrance feels of-a-piece.
   `> * { min-height: 0 }` lets grid items shrink below their intrinsic height when
   the row is 0fr — without it the body would refuse to collapse. */
:where([mono-accordion]) > [mono-body] {
  display: grid;
  grid-template-rows: 0fr;
  overflow: hidden;
  padding: 0 var(--_mono-accordion-pad-x);
  font-size: var(--_mono-accordion-body-font);
  line-height: var(--_mono-accordion-body-line-height);
  color: var(--_mono-accordion-body-color);
  border-top: var(--mono-border-width) solid transparent;

  /* Scope this body's layout/paint work to its own box. Measured effect: neutral on
     toggle cost, a modest win on the initial layout of a long list of accordions.
     (It is NOT what fixes sibling cost — Chrome already does not re-lay-out sibling
     subtrees when one accordion animates; that was measured, not assumed.)
     `paint` adds no new clipping — `overflow: hidden` above already clips. `layout`
     does make this a containing block + stacking context for absolutely positioned
     descendants, which is safe here because that same `overflow: hidden` already
     confined them, and mono's own popups are moved to a <body> portal. */
  contain: layout paint;

  transition:
    grid-template-rows var(--_mono-accordion-duration) var(--mono-ease),
    padding-top var(--_mono-accordion-duration) var(--mono-ease),
    padding-bottom var(--_mono-accordion-duration) var(--mono-ease),
    border-top-color var(--mono-duration) var(--mono-ease);
}
[mono-accordion] > [mono-body] > * {
  min-width: 0;
  min-height: 0;
}
/* Shadow build: the body's native <slot>s (`body` + the default one) default to
   `display: contents` and so have no box — slotted content would become the grid
   items directly (un-targetable by `> * { min-height: 0 }`) and keep the
   `grid-template-rows: 0fr → 1fr` track from ever collapsing. They sit in ONE
   `[mono-body-slots]` block, the single grid item (like the light build's
   <span data-mono-slot="body">), so the open/close collapse works. A bare `slot`
   child is kept for markup that still renders one. */
[mono-accordion] > [mono-body] > :is(slot, [mono-body-slots]) {
  display: block;
  min-width: 0;
  min-height: 0;
}
/* Standalone, the item IS the frame, so the open body is separated from the head
   by a hairline the way a card's footer is — EXTENSION, and the reason the top
   padding is not upstream's `pt-0` here. */
[mono-accordion][mono-open] > [mono-body] {
  grid-template-rows: 1fr;
  padding-top: var(--_mono-accordion-pad-y);
  padding-bottom: var(--_mono-accordion-pad-y);
  border-top-color: var(--_mono-accordion-border);
}
/* basecoat@1.0.2 styles/vega.css .accordion > details > :not(summary) — pt-0.
   In a group the head and its body are one run of text between two dividers,
   exactly as upstream renders it, so the top gap and the hairline both go. */
:where([mono-accordion-group], .mono-accordion-group) > [mono-accordion][mono-open] > [mono-body],
[mono-accordion][mono-grouped][mono-open] > [mono-body] {
  padding-top: 0;
  border-top-color: transparent;
}
/* A collapsed body is still fully rendered — the `0fr` track only hides it — so
   without this every closed accordion keeps its whole slotted subtree in the style,
   layout and paint trees. `content-visibility: hidden` drops it entirely.

   What this buys, measured with ~320-node bodies (Chromium, median of 3):
     initial layout, 40 panels: 157ms → 18ms, and flat in the panel count
     (5 panels: 52ms → 23ms). That is the cost of putting a long list of heavy
     accordions on screen at all — e.g. opening a modal that builds N entry forms.
   What it does NOT buy: a cheaper toggle. Skipping the subtree means an opening
   panel is laid out from scratch, so one open+close costs slightly MORE
   (23ms → 31ms at 40 panels). The toggle's real cost is the animation above —
   see `--mono-accordion-duration`.

   `allow-discrete` is what makes it safe to animate. Opening flips the property to
   `visible` at 0%, so the grid can still measure the content it is expanding to;
   closing holds it `visible` until 100%, so the collapse plays out before the content
   is dropped. Get that backwards and a closing body vanishes instantly instead of
   collapsing.

   Gated behind @supports deliberately. `content-visibility … allow-discrete` inside
   the `transition` SHORTHAND is a parse error to a browser without the feature, and a
   single bad entry drops the WHOLE declaration — which would take every accordion
   transition with it. Inside the guard the shorthand is known to parse, so the list is
   restated in full rather than patched with the `transition-behavior` longhand.
   Browsers without support keep exactly the previous behaviour.

   Must stay ABOVE the reduced-motion block: @supports adds no specificity, so source
   order is the only thing keeping `transition: none` the winner down there. */
@supports (transition-behavior: allow-discrete) {
  :where([mono-accordion]) > [mono-body] {
    content-visibility: hidden;
    /* Must stay `0`, NOT `auto 0`. `content-visibility: hidden` skips this element's
       own contents, so its size comes from HERE — and the `auto` keyword's remembered
       size is the panel's last OPEN height, which leaves a closed accordion holding
       full height with nothing in it. Tried, measured, reverted: a closed body read
       656px instead of collapsing. The scrollbar-stability that `auto` normally buys
       does not apply to an element that is itself the skipped one. */
    contain-intrinsic-size: 0;
    transition:
      grid-template-rows var(--_mono-accordion-duration) var(--mono-ease),
      padding-top var(--_mono-accordion-duration) var(--mono-ease),
      padding-bottom var(--_mono-accordion-duration) var(--mono-ease),
      border-top-color var(--mono-duration) var(--mono-ease),
      content-visibility var(--_mono-accordion-duration) allow-discrete;
  }

  [mono-accordion][mono-open] > [mono-body] {
    content-visibility: visible;
  }
}
@media (prefers-reduced-motion: reduce) {
  [mono-accordion],
  [mono-accordion] > [mono-head],
  [mono-accordion] > [mono-head] > [mono-arrow],
  [mono-accordion] > [mono-body] {
    transition: none;
  }
}
/* =========================================================================
   mono-chip — a port of Basecoat's `.badge` (basecoat-css@1.0.2, vega style).

   Styled by ATTRIBUTE, like Basecoat — and the attributes mirror the element's
   props one for one, so hand-written markup reads like the Lit / Vue tag:

     <mono-chip size="lg" color="success" variant="solid" label="Active" dot>
     <span mono-chip mono-size="lg" mono-color="success" mono-variant="solid" mono-has-dot>
       <span mono-main>
         <span mono-content>
           <span mono-dot></span>
           <span mono-label>Active</span>
           <button mono-close><span mono-glyph class="i-mdi-close"></span></button>
         </span>
       </span>
     </span>

   An absent attribute is the prop's default (`:not([mono-size])` = md,
   `:not([mono-color])` = primary, `:not([mono-variant])` = soft, no
   `mono-rounded` = the pill). The element renders these on its root (both
   builds) plus the states `mono-has-dot` (the dot PART is `mono-dot`, so the state
   spells itself out) / `mono-removable` / `mono-clickable` /
   `mono-disabled` / `mono-selected` and `mono-icon-position="right"`. The old
   classes (`.mono-chip.md.soft-primary`, `.chip-label`, `.chip-close`) are
   still emitted as inert hooks until 2.0 but no rule here reads them — except
   `rounded-<step>`, which is GONE: that is Tailwind/UnoCSS's own utility
   namespace, so on a page shipping those it was never inert (it rounded the
   chip's outer box). Use `mono-rounded` / the `rounded` prop.

   Selector map (ours ≡ upstream):
     [mono-chip]                   ≡ the layout box only — NOT painted (see below)
     [mono-main]                   ≡ .badge (inline-flex w-fit shrink-0 items-center
                                     justify-center overflow-hidden whitespace-nowrap,
                                     h-5 gap-1 rounded-4xl border border-transparent
                                     px-2 py-0.5 text-xs font-medium transition-all,
                                     focus-visible:border-ring ring-[3px] ring-ring/50)
     [mono-variant="solid"]        ≡ .badge[data-variant='primary'] (bg-c text-c-foreground,
                                     [a]:hover:bg-c/80) — generalised to every hue
     [mono-variant="soft"]         ≡ .badge[data-variant='destructive'] (bg-c/10 text-c,
                                     [a]:hover:bg-c/20, dark bg-c/20) — generalised; the DEFAULT
     [mono-variant="outline"]      ≡ .badge[data-variant='outline'] (border-border text-foreground,
                                     [a]:hover:bg-muted) + the hue on the edge and the ink
     [mono-color="secondary"]      ≡ .badge[data-variant='secondary'] (the muted surface pair)
     [mono-size="md"]              ≡ .badge's own h-5 px-2 text-xs; the other five are EXTENSION
                                     (Basecoat ships one badge size)
     [mono-rounded="…"]            ≡ EXTENSION (the shared corner ladder; unset = rounded-4xl)
     [mono-close]                  ≡ .combobox-chip-remove (opacity-50 hover:opacity-100, svg size-3.5)
     [mono-has-dot] / [mono-dot] / [mono-selected] / [mono-clickable] ≡ EXTENSION
     [mono-disabled]               ≡ .btn disabled:opacity-50
     [mono-status-dot]             ≡ EXTENSION (the standalone status-dot helper)

   WHY THE ROOT PAINTS NOTHING. `[mono-chip]` is also what a FIELD's internal
   chip carries: `<mono-tag-input>` renders Basecoat combobox chips as
   `[mono-chip] > [mono-chip-main] > …` and paints them in tag-input.css. Those
   rules are `[mono-tag-input] [mono-chip]` = (0,2,0) and win over this sheet,
   but only where they overlap — so this sheet keeps the root to layout plus
   custom properties (which a field's rules simply don't read) and paints the
   badge on `[mono-main]`, a part name a field chip does not have. The two never
   collide, and a real `<mono-chip>` slotted INTO a field keeps its own look.

   Specificity contract (same as the pre-port class sheet): a part's RESTING
   rule is exactly one attribute strong — `:where([mono-chip]) [mono-label]` =
   (0,1,0) — so a utility class handed in through `cssClass` wins by source
   order, while the prop and state rules stay heavier and win over it.

   Inner parts: [mono-main] > [mono-content] > [mono-dot] / [data-mono-slot=icon]
   / [mono-label] / [mono-close] > [mono-glyph].

   FLAVORS set `--mono-chip-{radius,border-width,font-weight,letter-spacing,
   text-transform}` and the VARIANT-scoped paint knobs
   `--mono-chip-{soft,solid,outline}-{bg,color,border-color}` (the shared
   `--mono-chip-bg` / `-color` is the CONSUMER's blanket override and repaints
   all three looks at once)` and the per-size `-height-<size>` /
   `-padding-x-<size>` / `-gap-<size>` / `-font-size-<size>` /
   `-glyph-size-<size>` (the size-agnostic twin of each of those is the
   CONSUMER's override — a flavor writing it would flatten the whole ladder);
   every fallback here is vega's value
   (`node scripts/basecoat-styles.mjs --varying "^\.badge"`).
   ========================================================================= */
mono-chip {
  display: inline-block;
}
/* =========================================
   Root — layout and the palette. NOTHING here paints (see the header).
   ========================================= */
[mono-chip] {
  /* ── the ten roles, each a public knob over a Basecoat token ──────────── */
  --_mono-chip-primary: var(--mono-chip-primary, var(--primary));
  --_mono-chip-primary-foreground: var(--mono-chip-primary-foreground, var(--primary-foreground));
  --_mono-chip-secondary: var(--mono-chip-secondary, var(--secondary));
  --_mono-chip-secondary-foreground: var(--mono-chip-secondary-foreground, var(--secondary-foreground));
  --_mono-chip-success: var(--mono-chip-success, var(--success));
  --_mono-chip-success-foreground: var(--mono-chip-success-foreground, var(--success-foreground));
  --_mono-chip-danger: var(--mono-chip-danger, var(--destructive));
  --_mono-chip-danger-foreground: var(--mono-chip-danger-foreground, var(--destructive-foreground));
  --_mono-chip-warning: var(--mono-chip-warning, var(--warning));
  --_mono-chip-warning-foreground: var(--mono-chip-warning-foreground, var(--warning-foreground));
  --_mono-chip-info: var(--mono-chip-info, var(--info));
  --_mono-chip-info-foreground: var(--mono-chip-info-foreground, var(--info-foreground));
  --_mono-chip-teal: var(--mono-chip-teal, var(--teal));
  --_mono-chip-teal-foreground: var(--mono-chip-teal-foreground, var(--teal-foreground));
  --_mono-chip-purple: var(--mono-chip-purple, var(--purple));
  --_mono-chip-purple-foreground: var(--mono-chip-purple-foreground, var(--purple-foreground));
  --_mono-chip-neutral: var(--mono-chip-neutral, var(--neutral));
  --_mono-chip-neutral-foreground: var(--mono-chip-neutral-foreground, var(--neutral-foreground));
  --_mono-chip-dark: var(--mono-chip-dark, var(--dark));
  --_mono-chip-dark-foreground: var(--mono-chip-dark-foreground, var(--dark-foreground));

  /* the colour in play — `primary` unless a [mono-color] rule re-points it */
  --_mono-chip-c: var(--_mono-chip-primary);
  --_mono-chip-c-foreground: var(--_mono-chip-primary-foreground);

  /* ── md metrics live on the unqualified root ON PURPOSE ────────────────────
     basecoat@1.0.2 styles/vega.css .badge — h-5 gap-1 rounded-4xl border
     border-transparent px-2 py-0.5 text-xs font-medium, [&>svg]:size-3 */
  --_mono-chip-height: var(--mono-chip-height, var(--_mono-chip-height-preset, var(--mono-chip-height-md, calc(var(--mono-spacing) * 5))));
  --_mono-chip-padding-x: var(--mono-chip-padding-x, var(--_mono-chip-padding-x-preset, var(--mono-chip-padding-x-md, calc(var(--mono-spacing) * 2))));
  --_mono-chip-gap: var(--mono-chip-gap, var(--_mono-chip-gap-preset, var(--mono-chip-gap-md, var(--mono-spacing))));
  --_mono-chip-font-size: var(--mono-chip-font-size, var(--_mono-chip-font-size-preset, var(--mono-chip-font-size-md, var(--mono-text-xs))));
  --_mono-chip-glyph-size: var(--mono-chip-glyph-size, var(--_mono-chip-glyph-size-preset, var(--mono-chip-glyph-size-md, calc(var(--mono-spacing) * 3))));
  /* `rounded-4xl` is the pill; a `rounded` step writes the preset tier, and an
     explicit --mono-chip-radius still wins over the prop */
  --_mono-chip-radius: var(--mono-chip-radius, var(--_mono-chip-radius-preset, var(--mono-radius-4xl)));
  --_mono-chip-border-width: var(--mono-chip-border-width, var(--mono-border-width));
  --_mono-chip-font-weight: var(--mono-chip-font-weight, var(--mono-font-weight-medium));

  --_mono-chip-ring-color: var(--mono-chip-ring-color, var(--ring));
  --_mono-chip-ring-width: var(--mono-chip-ring-width, var(--mono-ring-width));
  --_mono-chip-ring-alpha: var(--mono-chip-ring-alpha, var(--mono-ring-alpha));

  display: inline-flex;
  align-items: center;
  max-width: 100%;
  vertical-align: middle;
  line-height: 1;
}
/* =========================================
   The badge box — `.badge`
   ========================================= */
/* basecoat@1.0.2 components/badge.css .badge — inline-flex w-fit shrink-0
   items-center justify-center overflow-hidden whitespace-nowrap
   [&>svg]:pointer-events-none */
:where([mono-chip]) [mono-main] {
  display: inline-flex;
  width: fit-content;
  max-width: 100%;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  white-space: nowrap;
  box-sizing: border-box;
  height: var(--_mono-chip-height);
  gap: var(--_mono-chip-gap);
  padding-inline: var(--_mono-chip-padding-x);
  border: var(--_mono-chip-border-width) solid transparent;
  border-radius: var(--_mono-chip-radius);
  font-family: inherit;
  font-size: var(--_mono-chip-font-size);
  font-weight: var(--_mono-chip-font-weight);
  letter-spacing: var(--mono-chip-letter-spacing, normal);
  text-transform: var(--mono-chip-text-transform, none);
  line-height: 1;
  text-decoration: none;
  user-select: none;
  vertical-align: middle;
  /* `transition-all`, narrowed to what a chip actually animates */
  transition:
    color var(--mono-duration) var(--mono-ease),
    background-color var(--mono-duration) var(--mono-ease),
    border-color var(--mono-duration) var(--mono-ease),
    box-shadow var(--mono-duration) var(--mono-ease),
    opacity var(--mono-duration) var(--mono-ease);
  box-shadow: var(--_mono-chip-ring, 0 0 #0000);
}
/* A LINK chip is a control, not prose. Host stylesheets routinely paint a bare
   `a` — VitePress's own `.vp-doc a` sets a weight and an underline at (0,1,1) —
   and that out-specifies the (0,1,0) part rule above, so the anchor form
   restates what such a rule hijacks, one attribute heavier. Measured: the docs'
   light link chip came out at weight 500 while the shadow one, beyond that
   sheet's reach, kept the component's own 600. The colour needs no restatement:
   every variant rule is already (0,2,0).

   DEVIATION from the specificity contract, for this form only — a `cssClass.main`
   utility that sets font-weight or text-decoration on a LINK chip now needs
   `!important` (or the `--mono-chip-font-weight` knob). */
[mono-chip] a[mono-main] {
  font-weight: var(--_mono-chip-font-weight);
  text-decoration: none;
}
/* basecoat@1.0.2 components/badge.css .badge — focus-visible:border-ring
   focus-visible:ring-[3px] focus-visible:ring-ring/50 */
:where([mono-chip]) [mono-main]:focus-visible {
  outline: none;
  border-color: var(--_mono-chip-ring-color);
  --_mono-chip-ring: 0 0 0 var(--_mono-chip-ring-width)
    color-mix(in oklab, var(--_mono-chip-ring-color) var(--_mono-chip-ring-alpha), transparent);
}
/* =========================================
   Sizes — EXTENSION: Basecoat ships ONE badge; md is its `.badge`
   ========================================= */
/* The ladder steps the same way the control heights do: 4px of box and one type
   step per size, with md pinned to vega's h-5 / px-2 / text-xs. */
[mono-chip][mono-size="xs"] {
  --_mono-chip-height-preset: var(--mono-chip-height-xs, calc(var(--mono-spacing) * 4));
  --_mono-chip-padding-x-preset: var(--mono-chip-padding-x-xs, calc(var(--mono-spacing) * 1.5));
  --_mono-chip-gap-preset: var(--mono-chip-gap-xs, calc(var(--mono-spacing) * 0.75));
  --_mono-chip-font-size-preset: var(--mono-chip-font-size-xs, var(--mono-text-xs));
  --_mono-chip-glyph-size-preset: var(--mono-chip-glyph-size-xs, calc(var(--mono-spacing) * 2.5));
}
[mono-chip][mono-size="sm"] {
  --_mono-chip-height-preset: var(--mono-chip-height-sm, calc(var(--mono-spacing) * 4.5));
  --_mono-chip-padding-x-preset: var(--mono-chip-padding-x-sm, calc(var(--mono-spacing) * 1.75));
  --_mono-chip-gap-preset: var(--mono-chip-gap-sm, calc(var(--mono-spacing) * 0.875));
  --_mono-chip-font-size-preset: var(--mono-chip-font-size-sm, var(--mono-text-xs));
  --_mono-chip-glyph-size-preset: var(--mono-chip-glyph-size-sm, calc(var(--mono-spacing) * 2.75));
}
[mono-chip][mono-size="lg"] {
  --_mono-chip-height-preset: var(--mono-chip-height-lg, calc(var(--mono-spacing) * 6));
  --_mono-chip-padding-x-preset: var(--mono-chip-padding-x-lg, calc(var(--mono-spacing) * 2.5));
  --_mono-chip-gap-preset: var(--mono-chip-gap-lg, calc(var(--mono-spacing) * 1.25));
  --_mono-chip-font-size-preset: var(--mono-chip-font-size-lg, var(--mono-text-sm));
  --_mono-chip-glyph-size-preset: var(--mono-chip-glyph-size-lg, calc(var(--mono-spacing) * 3.5));
}
[mono-chip][mono-size="xl"] {
  --_mono-chip-height-preset: var(--mono-chip-height-xl, calc(var(--mono-spacing) * 7));
  --_mono-chip-padding-x-preset: var(--mono-chip-padding-x-xl, calc(var(--mono-spacing) * 3));
  --_mono-chip-gap-preset: var(--mono-chip-gap-xl, calc(var(--mono-spacing) * 1.5));
  --_mono-chip-font-size-preset: var(--mono-chip-font-size-xl, var(--mono-text-sm));
  --_mono-chip-glyph-size-preset: var(--mono-chip-glyph-size-xl, calc(var(--mono-spacing) * 4));
}
[mono-chip][mono-size="xxl"] {
  --_mono-chip-height-preset: var(--mono-chip-height-xxl, calc(var(--mono-spacing) * 8));
  --_mono-chip-padding-x-preset: var(--mono-chip-padding-x-xxl, calc(var(--mono-spacing) * 3.5));
  --_mono-chip-gap-preset: var(--mono-chip-gap-xxl, calc(var(--mono-spacing) * 1.75));
  --_mono-chip-font-size-preset: var(--mono-chip-font-size-xxl, var(--mono-text-base));
  --_mono-chip-glyph-size-preset: var(--mono-chip-glyph-size-xxl, calc(var(--mono-spacing) * 4.5));
}
/* =========================================
   Rounded — EXTENSION: the shared corner ladder. Unset is vega's rounded-4xl.
   ========================================= */
[mono-chip][mono-rounded="none"] { --_mono-chip-radius-preset: 0; }
[mono-chip][mono-rounded="xs"] { --_mono-chip-radius-preset: calc(var(--mono-radius-sm) / 2); }
[mono-chip][mono-rounded="sm"] { --_mono-chip-radius-preset: var(--mono-radius-sm); }
[mono-chip][mono-rounded="md"] { --_mono-chip-radius-preset: var(--mono-radius-md); }
[mono-chip][mono-rounded="lg"] { --_mono-chip-radius-preset: var(--mono-radius-lg); }
[mono-chip][mono-rounded="xl"] { --_mono-chip-radius-preset: var(--mono-radius-xl); }
[mono-chip][mono-rounded="xxl"] { --_mono-chip-radius-preset: var(--mono-radius-2xl); }
[mono-chip][mono-rounded="full"] { --_mono-chip-radius-preset: var(--mono-radius-full); }
/* =========================================
   Colours — each publishes the pair the variants read
   ========================================= */
[mono-chip][mono-color="primary"] {
  --_mono-chip-c: var(--_mono-chip-primary);
  --_mono-chip-c-foreground: var(--_mono-chip-primary-foreground);
}
/* basecoat@1.0.2 styles/vega.css .badge[data-variant='secondary'] —
   bg-secondary text-secondary-foreground: a SURFACE pair, not a hue, so its
   `soft` and `solid` land on the same muted plate (shadcn's meaning). */
[mono-chip][mono-color="secondary"] {
  --_mono-chip-c: var(--_mono-chip-secondary);
  --_mono-chip-c-foreground: var(--_mono-chip-secondary-foreground);
}
[mono-chip][mono-color="success"] {
  --_mono-chip-c: var(--_mono-chip-success);
  --_mono-chip-c-foreground: var(--_mono-chip-success-foreground);
}
[mono-chip][mono-color="danger"] {
  --_mono-chip-c: var(--_mono-chip-danger);
  --_mono-chip-c-foreground: var(--_mono-chip-danger-foreground);
}
[mono-chip][mono-color="warning"] {
  --_mono-chip-c: var(--_mono-chip-warning);
  --_mono-chip-c-foreground: var(--_mono-chip-warning-foreground);
}
[mono-chip][mono-color="info"] {
  --_mono-chip-c: var(--_mono-chip-info);
  --_mono-chip-c-foreground: var(--_mono-chip-info-foreground);
}
[mono-chip][mono-color="teal"] {
  --_mono-chip-c: var(--_mono-chip-teal);
  --_mono-chip-c-foreground: var(--_mono-chip-teal-foreground);
}
[mono-chip][mono-color="purple"] {
  --_mono-chip-c: var(--_mono-chip-purple);
  --_mono-chip-c-foreground: var(--_mono-chip-purple-foreground);
}
[mono-chip][mono-color="neutral"] {
  --_mono-chip-c: var(--_mono-chip-neutral);
  --_mono-chip-c-foreground: var(--_mono-chip-neutral-foreground);
}
[mono-chip][mono-color="dark"] {
  --_mono-chip-c: var(--_mono-chip-dark);
  --_mono-chip-c-foreground: var(--_mono-chip-dark-foreground);
}
/* =========================================
   Variants
   ========================================= */
/* `soft` is the DEFAULT and is Basecoat's tonal badge.
   basecoat@1.0.2 styles/vega.css .badge[data-variant='destructive'] —
   bg-destructive/10 text-destructive dark:bg-destructive/20 (the alpha pair
   travels as --mono-mode-tint, which is what makes it dark-mode correct). */
[mono-chip]:is(:not([mono-variant]), [mono-variant="soft"]) > [mono-main] {
  background-color: var(--mono-chip-bg, var(--mono-chip-soft-bg, color-mix(in oklab, var(--_mono-chip-c) var(--mono-mode-tint), transparent)));
  color: var(--mono-chip-color, var(--mono-chip-soft-color, var(--_mono-chip-c)));
  border-color: var(--mono-chip-border-color, var(--mono-chip-soft-border-color, transparent));
}
/* `secondary` is a surface, not a hue: tinting it would wash it out, so the
   soft chip wears the plate itself (`.badge[data-variant='secondary']`). */
[mono-chip][mono-color="secondary"]:is(:not([mono-variant]), [mono-variant="soft"]) > [mono-main] {
  background-color: var(--mono-chip-bg, var(--mono-chip-soft-bg, var(--_mono-chip-secondary)));
  color: var(--mono-chip-color, var(--mono-chip-soft-color, var(--_mono-chip-secondary-foreground)));
}
/* basecoat@1.0.2 styles/vega.css .badge:not([data-variant]), .badge[data-variant='primary']
   — bg-primary text-primary-foreground */
[mono-chip][mono-variant="solid"] > [mono-main] {
  background-color: var(--mono-chip-bg, var(--mono-chip-solid-bg, var(--_mono-chip-c)));
  color: var(--mono-chip-color, var(--mono-chip-solid-color, var(--_mono-chip-c-foreground)));
  border-color: var(--mono-chip-border-color, var(--mono-chip-solid-border-color, transparent));
}
/* basecoat@1.0.2 styles/vega.css .badge[data-variant='outline'] — border-border
   text-foreground — EXTENSION: the edge and the ink take the role's colour so
   `outline` reads as the same family as the other two. */
[mono-chip][mono-variant="outline"] > [mono-main] {
  background-color: var(--mono-chip-bg, var(--mono-chip-outline-bg, transparent));
  color: var(--mono-chip-color, var(--mono-chip-outline-color, var(--_mono-chip-c)));
  border-color: var(--mono-chip-border-color, var(--mono-chip-outline-border-color, var(--_mono-chip-c)));
}
[mono-chip][mono-color="secondary"][mono-variant="outline"] > [mono-main] {
  color: var(--mono-chip-color, var(--foreground));
  border-color: var(--mono-chip-border-color, var(--border));
}
/* =========================================
   Interactive — a clickable / linked chip
   ========================================= */
/* basecoat@1.0.2 styles/vega.css .badge:not([data-variant]), .badge[data-variant='primary']
   — [a]:hover:bg-primary/80: only a LINK badge reacts upstream; ours also
   reacts when `clickable` made it a button (same gesture, no href). */
[mono-chip][mono-clickable] > [mono-main] {
  cursor: pointer;
}
@media (hover: hover) {
  [mono-chip][mono-clickable]:not([mono-disabled])[mono-variant="solid"] > [mono-main]:hover {
    background-color: color-mix(in oklab, var(--_mono-chip-c) 80%, transparent);
  }

  /* .badge[data-variant='destructive'] — [a]:hover:bg-destructive/20 */
  [mono-chip][mono-clickable]:not([mono-disabled]):is(:not([mono-variant]), [mono-variant="soft"]) > [mono-main]:hover {
    background-color: color-mix(in oklab, var(--_mono-chip-c) var(--mono-mode-tint-hover), transparent);
  }

  /* `secondary` is a plate, not a tint: darken it the way the secondary button
     does (basecoat@1.0.2 styles/vega.css .btn[data-variant='secondary']). */
  [mono-chip][mono-clickable]:not([mono-disabled])[mono-color="secondary"]:is(:not([mono-variant]), [mono-variant="soft"]) > [mono-main]:hover {
    background-color: color-mix(in oklch, var(--_mono-chip-secondary), var(--foreground) 5%);
  }

  /* .badge[data-variant='outline'] — [a]:hover:bg-muted */
  [mono-chip][mono-clickable]:not([mono-disabled])[mono-variant="outline"] > [mono-main]:hover {
    background-color: var(--mono-mode-ghost-hover);
  }
}
/* EXTENSION — `selected` rings the chip in its own colour, the one state
   Basecoat's badge has no equivalent for (it is not a toggle upstream). */
[mono-chip][mono-selected] > [mono-main] {
  --_mono-chip-ring: 0 0 0 var(--_mono-chip-ring-width)
    color-mix(in oklab, var(--_mono-chip-c) var(--_mono-chip-ring-alpha), transparent);
  border-color: var(--_mono-chip-c);
}
/* basecoat@1.0.2 components/button.css .btn — disabled:pointer-events-none
   disabled:opacity-50 */
[mono-chip][mono-disabled] > [mono-main] {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}
/* =========================================
   Inner content
   ========================================= */
:where([mono-chip]) [mono-content] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: inherit;
  min-width: 0;
  max-width: 100%;
  height: 100%;
  line-height: 1;
}
:where([mono-chip]) [mono-label] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1;
}
/* EXTENSION — the leading status dot. It is the role's colour at full strength,
   which reads on both the tinted `soft` plate and the solid one (`currentColor`
   there). */
:where([mono-chip]) [mono-dot] {
  flex: 0 0 auto;
  width: var(--mono-chip-dot-size, calc(var(--mono-spacing) * 1.5));
  height: var(--mono-chip-dot-size, calc(var(--mono-spacing) * 1.5));
  border-radius: var(--mono-radius-full);
  background: currentColor;
}
/* The shadow build renders the icon wrapper on every chip and marks the empty
   one; this hides it so both builds measure the same content box. */
[mono-chip] [data-mono-slot="icon"][mono-empty] {
  display: none;
}
/* `[&>svg]:size-3!` — our icon is a slotted element or a mask span, sized by
   the same token as the close glyph */
:where([mono-chip]) [data-mono-slot="icon"],
:where([mono-chip]) [mono-main] > svg {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: var(--_mono-chip-glyph-size);
  height: var(--_mono-chip-glyph-size);
  line-height: 1;
  pointer-events: none;
}
:where([mono-chip]) [data-mono-slot="icon"] > * {
  display: block;
  width: 100%;
  height: 100%;
}
/* basecoat@1.0.2 styles/vega.css .combobox-chip-remove — -ms-1 opacity-50
   hover:opacity-100, [&>svg]:size-3.5 — the same affordance a field chip uses */
:where([mono-chip]) [mono-close] {
  appearance: none;
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: var(--_mono-chip-glyph-size);
  height: var(--_mono-chip-glyph-size);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--mono-radius-full);
  background: transparent;
  color: inherit;
  font: inherit;
  line-height: 1;
  cursor: pointer;
  opacity: 0.5;
  transition:
    opacity var(--mono-duration) var(--mono-ease),
    box-shadow var(--mono-duration) var(--mono-ease);
  box-shadow: var(--_mono-chip-close-ring, 0 0 #0000);
}
@media (hover: hover) {
  :where([mono-chip]) [mono-close]:hover {
    opacity: 1;
  }
