/* `sm:gap-2.5` — the row breathes once there is room for it. */
@media (min-width: 640px) {
  :where([mono-breadcrumb]) [mono-list] {
    gap: var(--_mono-breadcrumb-gap-wide);
  }
}
/* `truncate` CLAMPS, it does not force one line. Forcing `nowrap` meant the
   row either overflowed its container or — once the crumbs were allowed to
   shrink — squeezed short labels that had room, so `Dashboard` came out as
   `Dash…` next to a half-empty row. Wrapping keeps every label at its clamp and
   breaks the line instead. */
/* VitePress puts `margin-top: 8px` on `li + li` and `margin-bottom: .5em` on
   every `li`; either one stops the separators centring with the actions. */
:where([mono-breadcrumb]) [mono-list] :is([mono-item], [mono-separator]) {
  margin: 0;
  padding: 0;
  list-style: none;
}
/* A composed child list renders a separator BEFORE each of its items, since it
   cannot know whether it is the first sibling. The very first one is dropped. */
[mono-list] > mono-breadcrumb-list:first-child > [mono-separator]:first-child {
  display: none;
}
/* =========================================
   Item
   ========================================= */
/* basecoat@1.0.2 styles/vega.css .breadcrumb li — gap-1.5 */
/* basecoat@1.0.2 components/breadcrumb.css .breadcrumb li — inline-flex items-center */
:where([mono-breadcrumb]) [mono-item] {
  display: inline-flex;
  align-items: center;
  align-self: center;
  gap: var(--_mono-breadcrumb-gap);
  min-width: 0;
}
/* =========================================
   Action — the segment itself
   ========================================= */
/* basecoat@1.0.2 components/breadcrumb.css .breadcrumb a — rounded-sm outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50 */
/* basecoat@1.0.2 styles/vega.css .breadcrumb a — transition-colors hover:text-foreground
   DEVIATION: upstream's <a> is bare text. The padding and the border are kept as
   knobs at 0 so `contained` / `underlined` — and a consumer — can turn the
   segment into a chip without a second rule. */
:where([mono-breadcrumb]) [mono-action] {
  display: inline-flex;
  align-items: center;
  gap: var(--_mono-breadcrumb-gap);
  padding: var(--_mono-breadcrumb-pad-y) var(--_mono-breadcrumb-pad-x);
  border: var(--_mono-breadcrumb-border-width) solid transparent;
  border-radius: var(--_mono-breadcrumb-radius);
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: var(--_mono-breadcrumb-font-weight);
  text-align: left;
  text-decoration: none;
  white-space: nowrap;
  user-select: none;
  outline: none;
  transition:
    color var(--mono-duration) var(--mono-ease),
    background-color var(--mono-duration) var(--mono-ease),
    border-color var(--mono-duration) var(--mono-ease);
}
:where([mono-breadcrumb]) :is(a, button)[mono-action] {
  cursor: pointer;
}
:where([mono-breadcrumb]) span[mono-action] {
  cursor: default;
}
/* VitePress's `.vp-doc a` (0,1,1) underlines and re-inks every link, and adds an
   external-link glyph on `target="_blank"`. The current segment renders as a
   <span>, so it is never reached. */
[mono-breadcrumb] a[mono-action] {
  text-decoration: none;
  color: inherit;
  font-weight: var(--_mono-breadcrumb-font-weight);
}
[mono-breadcrumb] a[mono-action]::after {
  display: none !important;
}
@media (hover: hover) {
  [mono-breadcrumb] :is(a, button)[mono-action]:hover {
    color: var(--_mono-breadcrumb-accent);
  }
}
/* `focus-visible:ring-[3px] focus-visible:ring-ring/50` */
[mono-breadcrumb] [mono-action]:focus-visible {
  outline: none;
  box-shadow: 0 0 0 var(--mono-ring-width-lg, 3px)
    color-mix(in oklab, var(--ring) 50%, transparent);
}
/* basecoat@1.0.2 styles/vega.css .breadcrumb [aria-current='page'] — font-normal text-foreground */
/* basecoat@1.0.2 components/breadcrumb.css .breadcrumb [aria-current='page'] — cursor-default */
[mono-breadcrumb] [mono-item][mono-current] > [mono-action] {
  color: var(--_mono-breadcrumb-accent);
  font-weight: var(--_mono-breadcrumb-current-weight);
  text-transform: var(--_mono-breadcrumb-current-transform);
  letter-spacing: var(--_mono-breadcrumb-current-tracking);
  cursor: default;
}
[mono-breadcrumb] [mono-item][mono-disabled] > [mono-action],
[mono-breadcrumb] [mono-action]:disabled,
[mono-breadcrumb][mono-disabled] [mono-action] {
  opacity: var(--mono-disabled-opacity, 0.5);
  cursor: not-allowed;
  pointer-events: none;
}
/* =========================================
   Variant: contained — EXTENSION, the pre-port chip
   ========================================= */
[mono-breadcrumb][mono-variant="contained"] {
  --_mono-breadcrumb-pad-x-preset: var(--mono-breadcrumb-contained-pad-x, calc(var(--mono-spacing) * 2));
  --_mono-breadcrumb-pad-y-preset: var(--mono-breadcrumb-contained-pad-y, calc(var(--mono-spacing) * 1));
}
[mono-breadcrumb][mono-variant="contained"] [mono-action] {
  background: var(--_mono-breadcrumb-surface);
  border-color: var(--_mono-breadcrumb-border);
}
@media (hover: hover) {
  [mono-breadcrumb][mono-variant="contained"] :is(a, button)[mono-action]:hover {
    background: color-mix(in oklab, var(--_mono-breadcrumb-accent) var(--mono-mode-tint), transparent);
    border-color: color-mix(in oklab, var(--_mono-breadcrumb-accent) var(--mono-mode-checked-border), transparent);
  }
}
/* The flat role fill, not the old gradient-and-glow. */
[mono-breadcrumb][mono-variant="contained"] [mono-item][mono-current] > [mono-action] {
  background: var(--_mono-breadcrumb-accent);
  border-color: transparent;
  color: var(--_mono-breadcrumb-on-accent);
}
[mono-breadcrumb][mono-variant="contained"] [mono-item][mono-current] > [mono-action] [mono-badge] {
  background: color-mix(in oklab, var(--_mono-breadcrumb-on-accent) 22%, transparent);
  color: var(--_mono-breadcrumb-on-accent);
}
/* =========================================
   Variant: underlined — EXTENSION
   ========================================= */
[mono-breadcrumb][mono-variant="underlined"] [mono-action] {
  border-radius: 0;
  border-bottom-color: transparent;
}
@media (hover: hover) {
  [mono-breadcrumb][mono-variant="underlined"] :is(a, button)[mono-action]:hover {
    border-bottom-color: color-mix(in oklab, var(--_mono-breadcrumb-accent) var(--mono-mode-checked-border), transparent);
  }
}
[mono-breadcrumb][mono-variant="underlined"] [mono-item][mono-current] > [mono-action] {
  border-bottom-color: var(--_mono-breadcrumb-accent);
}
/* =========================================
   Icon
   ========================================= */
/* basecoat@1.0.2 components/breadcrumb.css .breadcrumb li > span[aria-hidden='true'] — flex items-center justify-center */
/* basecoat@1.0.2 styles/vega.css .breadcrumb li > span[aria-hidden='true'] — size-5 [&>svg]:size-4 */
:where([mono-breadcrumb]) [mono-icon] {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_mono-breadcrumb-icon-size);
  height: var(--_mono-breadcrumb-icon-size);
  font-size: var(--_mono-breadcrumb-icon-size);
  line-height: 1;
}
/* Three shapes end up inside the box and all must fill it:
     shadow build, user-slotted → <slot> → ::slotted(svg)
     light build, user-slotted  → <span data-mono-slot="icon-<id>"> → svg
     inline `item.icon` markup  → a direct child svg
   The light placeholder is the subtle one: it parks the captured child, so the
   SVG is a GRANDchild and a `> svg` rule misses it entirely. */
[mono-icon] > svg,
[mono-icon] > [data-mono-slot] > svg,
[mono-icon] slot::slotted(svg) {
  display: block;
  width: 100%;
  height: 100%;
}
/* The placeholder must not become a 0-width flex item between the box and the
   SVG — `display: contents` drops it from layout so the SVG sizes against the
   box instead of against a zero-width parent. */
[mono-icon] > [data-mono-slot] {
  display: contents;
}
/* Class + attribute = specificity (0,2,0), deliberately. UnoCSS's `i-…`
   utilities set `width`/`height: 1.2em` (presetIcons `scale: 1.2`) at (0,1,0)
   and their sheet loads AFTER this one, so a single selector loses and the glyph
   overflows its box. Two selectors win regardless of sheet order — and it is the
   only thing that works for the SHADOW build, where this span is a LIGHT-DOM
   child of the host that no shadow-scoped selector can reach.
   Scoped to the breadcrumb: its OWN class (every build sets it on the span — the
   shadow build's span is a light-DOM child of the host, outside [mono-breadcrumb])
   OR anything inside a [mono-breadcrumb] root (raw CSS markup writes a bare
   `<span mono-glyph class="i-…">`). Still (0,2,0): `:is()` weighs its heaviest
   argument. A bare `[mono-glyph][mono-glyph]` is global and stretched every other
   component's `[mono-glyph]` to 100% — the accordion's icon chip filled its header. */
:is(.mono-breadcrumb-iconify, [mono-breadcrumb] *)[mono-glyph] {
  display: inline-block;
  width: 100%;
  height: 100%;
  flex-shrink: 0;
  color: inherit;
}
/* =========================================
   Content / title
   ========================================= */
:where([mono-breadcrumb]) [mono-content] {
  display: inline-flex;
  align-items: center;
  min-width: 0;
}
:where([mono-breadcrumb]) [mono-title] {
  font-size: inherit;
  font-weight: inherit;
  color: inherit;
  line-height: inherit;
}
/* A flex item's `min-width` is `auto` — its content — so without this the
   crumbs could not shrink past their clamp and the row simply overflowed its
   container (measured: 543px of crumbs in a 512px box). Letting the chain go to
   zero turns the clamp into a CEILING: a crumb takes at most `truncate-width`,
   and less when the row is tight. */
[mono-breadcrumb][mono-truncate] :is([mono-item], [mono-action], [mono-content]) {
  min-width: 0;
}
[mono-breadcrumb][mono-truncate] [mono-title] {
  display: block;
  max-width: var(--mono-breadcrumb-truncate-width, 12ch);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
[mono-breadcrumb][mono-truncate] [mono-item][mono-current] [mono-title] {
  max-width: var(--mono-breadcrumb-truncate-width-current, 18ch);
}
/* =========================================
   Badge — EXTENSION, borrowing `.badge`'s shape
   ========================================= */
/* basecoat@1.0.2 styles/vega.css .badge — h-5 gap-1 rounded-4xl border border-transparent px-2 py-0.5 text-xs font-medium transition-all [&>svg]:size-3! */
:where([mono-breadcrumb]) [mono-badge] {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--mono-spacing);
  height: var(--_mono-breadcrumb-badge-height);
  padding: 0 var(--_mono-breadcrumb-badge-pad-x);
  border: var(--mono-border-width) solid transparent;
  border-radius: var(--_mono-breadcrumb-badge-radius);
  font-size: var(--_mono-breadcrumb-badge-font);
  font-weight: var(--_mono-breadcrumb-badge-weight);
  line-height: 1;
  background: var(--_mono-breadcrumb-badge-bg);
  color: var(--_mono-breadcrumb-badge-color);
}
/* The roles ink the pill tonally — the same wash the ported chip and menu use. */
[mono-breadcrumb] [mono-badge="primary"] {
  background: color-mix(in oklab, var(--_mono-breadcrumb-primary) var(--mono-mode-tint), transparent);
  color: var(--_mono-breadcrumb-primary);
}
[mono-breadcrumb] [mono-badge="success"] {
  background: color-mix(in oklab, var(--_mono-breadcrumb-success) var(--mono-mode-tint), transparent);
  color: var(--_mono-breadcrumb-success);
}
[mono-breadcrumb] [mono-badge="danger"] {
  background: color-mix(in oklab, var(--_mono-breadcrumb-danger) var(--mono-mode-tint), transparent);
  color: var(--_mono-breadcrumb-danger);
}
[mono-breadcrumb] [mono-badge="warning"] {
  background: color-mix(in oklab, var(--_mono-breadcrumb-warning) var(--mono-mode-tint), transparent);
  color: var(--_mono-breadcrumb-warning);
}
[mono-breadcrumb] [mono-badge="info"] {
  background: color-mix(in oklab, var(--_mono-breadcrumb-info) var(--mono-mode-tint), transparent);
  color: var(--_mono-breadcrumb-info);
}
/* =========================================
   Separator
   ========================================= */
/* basecoat@1.0.2 components/breadcrumb.css .breadcrumb li[aria-hidden='true'] — select-none */
:where([mono-breadcrumb]) [mono-separator] {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: center;
  /* Upstream's separator is an SVG at `size-3.5`, so the slot between two
     crumbs is 14px wide whatever is in it. A text glyph like `›` is barely 4px,
     which — on a flavor with a tight gap — left the labels all but touching.
     Reserving the same box is what keeps the row legible either way. */
  min-width: var(--_mono-breadcrumb-sep-size);
  font-size: var(--_mono-breadcrumb-sep-font);
  line-height: 1;
  color: var(--_mono-breadcrumb-sep-color);
  user-select: none;
}
/* basecoat@1.0.2 styles/vega.css .breadcrumb li[aria-hidden='true'] > svg — size-3.5 */
[mono-separator] > svg,
[mono-separator] > [data-mono-slot] > svg,
[mono-separator] slot::slotted(svg) {
  display: block;
  width: var(--_mono-breadcrumb-sep-size);
  height: var(--_mono-breadcrumb-sep-size);
}
[mono-separator] > [data-mono-slot] {
  display: contents;
}
/* basecoat@1.0.2 components/breadcrumb.css .breadcrumb [data-rtl-flip] — rtl:rotate-180 */
[dir="rtl"] [mono-breadcrumb] [mono-separator] > svg {
  rotate: 180deg;
}
/* =========================================
   Reduced motion
   ========================================= */
@media (prefers-reduced-motion: reduce) {
  [mono-breadcrumb] [mono-action] {
    transition: none;
  }
}
/* =========================================================================
   mono-button — a port of Basecoat's `.btn` (basecoat-css@1.0.2, vega style).

   Styled by ATTRIBUTE, like Basecoat (`.btn[data-size='sm']`) — and the
   attributes mirror the element's props one for one, so hand-written markup
   reads like the Lit / Vue tag:

     <mono-button size="sm" color="danger" variant="outline" rounded="full">
     <div mono-button mono-size="sm" mono-color="danger" mono-variant="outline" mono-rounded="full">
       <button>…</button>
     </div>

   An absent attribute is the prop's default (`:not([mono-size])` = md,
   `:not([mono-color])` = primary, `:not([mono-variant])` = solid). The element
   renders these attributes on its wrapper (both builds); the old classes
   (`.mono-button.sm.outline-primary`) are still emitted as inert hooks for
   consumer CSS until 2.0 but no rule here reads them.

   Selector map (ours ≡ upstream):
     [mono-button] > :is(button, a)                ≡ .btn
     [mono-size="xs|sm|md|lg"]                     ≡ .btn[data-size='xs'|'sm'|default|'lg']
     [mono-size="xl|xxl"]                          ≡ EXTENSION (h-11 / h-12 on the same grid)
     [mono-icon-only][mono-size=…]                 ≡ .btn[data-size='icon-<size>']
     [mono-variant="solid"][mono-color=<hue>]      ≡ .btn[data-variant='primary'] with the hue swapped
     [mono-variant="solid"][mono-color="secondary"]≡ .btn[data-variant='secondary']
     [mono-variant="solid"][mono-color="light"]    ≡ .btn[data-variant='outline']
     [mono-variant="outline"][mono-color=<hue>]    ≡ EXTENSION (outline pattern, hue-inked)
     [mono-variant="tonal"][mono-color=<hue>]      ≡ .btn[data-variant='destructive'] with the hue swapped
     [mono-variant="text"]                         ≡ .btn[data-variant='ghost'] (+ hue ink)
     [mono-link]                                   ≡ .btn[data-variant='link']
     [mono-content] > [mono-icon]:first/last-child ≡ has-[[data-icon='inline-start'|'inline-end']]
     [mono-affix="prepend|append"]                 ≡ .button-group siblings

   Inner parts are attributes too, so a hand-written button is attributes all
   the way down: [mono-native] on the <button>/<a>, [mono-content],
   [mono-icon] (+ [mono-spinning] / [mono-empty] / [mono-hidden]), [mono-text],
   [mono-badge="red|green|orange|cobalt"], [mono-affix="prepend|append"]
   (+ [mono-divider] / [mono-disabled] / [mono-empty]).

   Values are copied from the compiled vendor sheet (vendor/basecoat/basecoat-
   vega.cdn.css) through the token layer: `--spacing` → `--mono-spacing`,
   `--text-sm` → `--mono-text-sm`, `--radius-md` → `--mono-radius-md`,
   `--color-x` → `--x`, Tailwind's `--tw-ring-*` stack → the two-slot
   `box-shadow: ring, shadow` below, and every `dark:` variant → a
   `--mono-mode-*` token (a selector cannot cross a shadow boundary; an
   inherited custom property can).

   FLAVORS (Basecoat's other seven styles, src/data/theme/flavors/*.css) set the
   `--mono-button-<size>-*` style knobs read below — `-radius`, `-padding-inline`,
   `-icon-padding`, `-gap`, `-font-size`, `-line-height`, `-icon-size` — plus
   `--mono-button-font-weight` / `-text-transform` / `-letter-spacing` /
   `-icon-size` / `-outline-shadow` / `-outline-bg` / `-outline-hover-bg` /
   `-link-decoration`. Every fallback here is vega's value
   (`node scripts/basecoat-styles.mjs --varying "^\.btn"` prints the matrix).

   The public `--mono-button-*` knobs and the three-tier resolver
   (`--mono-button-x` → `--_mono-button-x-preset` → base) are unchanged: a
   colour/variant class only ever writes a `*-preset` slot, so a consumer's
   own `--mono-button-bg` on the host still wins.
   ========================================================================= */
mono-button {
  display: inline-block;
}
[mono-button] {
  /* ── palette: each slot is a public knob over a Basecoat token ─────────── */
  --_mono-button-primary: var(--mono-button-primary, var(--primary));
  --_mono-button-primary-foreground: var(--mono-button-primary-foreground, var(--primary-foreground));
  --_mono-button-secondary: var(--mono-button-secondary, var(--secondary));
  --_mono-button-secondary-foreground: var(--mono-button-secondary-foreground, var(--secondary-foreground));
  --_mono-button-success: var(--mono-button-success, var(--success));
  --_mono-button-success-foreground: var(--mono-button-success-foreground, var(--success-foreground));
  --_mono-button-danger: var(--mono-button-danger, var(--destructive));
  --_mono-button-danger-foreground: var(--mono-button-danger-foreground, var(--destructive-foreground));
  --_mono-button-warning: var(--mono-button-warning, var(--warning));
  --_mono-button-warning-foreground: var(--mono-button-warning-foreground, var(--warning-foreground));
  --_mono-button-info: var(--mono-button-info, var(--info));
  --_mono-button-info-foreground: var(--mono-button-info-foreground, var(--info-foreground));
  --_mono-button-teal: var(--mono-button-teal, var(--teal));
  --_mono-button-teal-foreground: var(--mono-button-teal-foreground, var(--teal-foreground));
  --_mono-button-purple: var(--mono-button-purple, var(--purple));
  --_mono-button-purple-foreground: var(--mono-button-purple-foreground, var(--purple-foreground));
  --_mono-button-dark: var(--mono-button-dark, var(--dark));
  --_mono-button-dark-foreground: var(--mono-button-dark-foreground, var(--dark-foreground));
  --_mono-button-neutral: var(--mono-button-neutral, var(--neutral));
  --_mono-button-neutral-foreground: var(--mono-button-neutral-foreground, var(--neutral-foreground));
  --_mono-button-text: var(--mono-button-text, var(--foreground));
  --_mono-button-background: var(--mono-button-background, var(--background));
  --_mono-button-muted: var(--mono-button-muted, var(--muted));
  --_mono-button-border: var(--mono-button-border, var(--mono-mode-outline-border));

  /* ── tonal tint ramp: `bg-x/10 hover:bg-x/20` (dark 20 / 30) ────────────
     One alpha pair for every hue instead of the old srgb-with-white mixes;
     the per-colour `--mono-button-<c>-soft(-hover)` knobs below still win. */
  --_mono-button-tint: var(--mono-button-tint, var(--mono-mode-tint));
  --_mono-button-tint-hover: var(--mono-button-tint-hover, var(--mono-mode-tint-hover));
  --_mono-button-primary-soft: var(--mono-button-primary-soft, color-mix(in oklab, var(--_mono-button-primary) var(--_mono-button-tint), transparent));
  --_mono-button-primary-soft-hover: var(--mono-button-primary-soft-hover, color-mix(in oklab, var(--_mono-button-primary) var(--_mono-button-tint-hover), transparent));
  --_mono-button-success-soft: var(--mono-button-success-soft, color-mix(in oklab, var(--_mono-button-success) var(--_mono-button-tint), transparent));
  --_mono-button-success-soft-hover: var(--mono-button-success-soft-hover, color-mix(in oklab, var(--_mono-button-success) var(--_mono-button-tint-hover), transparent));
  --_mono-button-danger-soft: var(--mono-button-danger-soft, color-mix(in oklab, var(--_mono-button-danger) var(--_mono-button-tint), transparent));
  --_mono-button-danger-soft-hover: var(--mono-button-danger-soft-hover, color-mix(in oklab, var(--_mono-button-danger) var(--_mono-button-tint-hover), transparent));
  --_mono-button-warning-soft: var(--mono-button-warning-soft, color-mix(in oklab, var(--_mono-button-warning) var(--_mono-button-tint), transparent));
  --_mono-button-warning-soft-hover: var(--mono-button-warning-soft-hover, color-mix(in oklab, var(--_mono-button-warning) var(--_mono-button-tint-hover), transparent));
  --_mono-button-info-soft: var(--mono-button-info-soft, color-mix(in oklab, var(--_mono-button-info) var(--_mono-button-tint), transparent));
