  --_mono-bd-item-hover-color-preset: var(--_mono-bd-primary);
}
[mono-button-dropdown] [mono-item][mono-item-color="success"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-success);
  --_mono-bd-item-hover-bg-preset: color-mix(in oklab, var(--_mono-bd-success) var(--mono-mode-tint), transparent);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-success);
}
[mono-button-dropdown] [mono-item][mono-item-color="danger"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-danger);
  --_mono-bd-item-hover-bg-preset: color-mix(in oklab, var(--_mono-bd-danger) var(--mono-mode-tint), transparent);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-danger);
}
[mono-button-dropdown] [mono-item][mono-item-color="warning"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-warning);
  --_mono-bd-item-hover-bg-preset: color-mix(in oklab, var(--_mono-bd-warning) var(--mono-mode-tint), transparent);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-warning);
}
[mono-button-dropdown] [mono-item][mono-item-color="info"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-info);
  --_mono-bd-item-hover-bg-preset: color-mix(in oklab, var(--_mono-bd-info) var(--mono-mode-tint), transparent);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-info);
}
[mono-button-dropdown] [mono-item][mono-item-color="teal"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-teal);
  --_mono-bd-item-hover-bg-preset: color-mix(in oklab, var(--_mono-bd-teal) var(--mono-mode-tint), transparent);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-teal);
}
[mono-button-dropdown] [mono-item][mono-item-color="purple"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-purple);
  --_mono-bd-item-hover-bg-preset: color-mix(in oklab, var(--_mono-bd-purple) var(--mono-mode-tint), transparent);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-purple);
