/* The three surface roles: their ink is a foreground, and a 10% wash of a
   near-background colour is invisible — so they hover on `--accent`, the
   neutral row wash, exactly like an uncoloured entry. */
[mono-button-dropdown] [mono-item][mono-item-color="dark"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-dark);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-dark);
}
[mono-button-dropdown] [mono-item][mono-item-color="secondary"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-secondary);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-secondary);
}
[mono-button-dropdown] [mono-item][mono-item-color="light"] {
  --_mono-bd-item-color-preset: var(--_mono-bd-light);
  --_mono-bd-item-hover-color-preset: var(--_mono-bd-light);
