  font-size: var(--_mono-card-title-font);
  line-height: var(--mono-card-title-line-height, var(--mono-leading-normal));
  font-weight: var(--mono-card-title-font-weight, var(--mono-font-weight-medium));
  letter-spacing: var(--mono-card-title-tracking, normal);
