:where([mono-card]) [mono-subtitle] {
  margin: 0;
  font-size: var(--_mono-card-subtitle-font);
  line-height: var(--mono-card-subtitle-line-height, var(--mono-leading-normal));
  font-weight: var(--mono-font-weight-normal);
  color: var(--_mono-card-subtext);
