  height: var(--_mono-card-icon-size);
  border-radius: var(--mono-card-icon-radius, var(--mono-radius-md));
  line-height: 1;
  background-color: color-mix(in oklab, var(--_mono-card-accent) var(--mono-mode-tint), transparent);
  color: var(--_mono-card-accent);
  overflow: hidden;
