  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--_mono-card-actions-gap);
  padding-inline: var(--_mono-card-padding);
}
:where([mono-card]) > [mono-actions] {
  justify-content: flex-end;
