  padding-bottom: var(--_mono-card-padding);
  border-bottom: var(--mono-border-width) solid var(--_mono-card-divider-color);
}
[mono-card]:not([mono-no-footer-divider]) > :is([mono-actions], [mono-footer]):not([mono-empty]) {
  padding-top: var(--_mono-card-padding);
  border-top: var(--mono-border-width) solid var(--_mono-card-divider-color);
}
/* =========================================
   Media — a full-bleed band; upstream gives the first/last child image the
   card's own corners and drops the padding on that edge
   ========================================= */
