     --_mono-chart-1 … -5                  ≡ --chart-1 … --chart-5 (the default palette, in that order)
     --_mono-chart-primary                 ≡ --primary
     --_mono-chart-secondary               ≡ --muted-foreground (the "secondary" ink every field uses)
     --_mono-chart-accent                  ≡ --chart-2 (Basecoat's --accent is a surface, not a series colour)
     --_mono-chart-success/warning/danger/info ≡ --success / --warning / --destructive / --info
     --_mono-chart-text                    ≡ --foreground (legend, title)
     --_mono-chart-muted                   ≡ --muted-foreground (axis ticks, the empty message)
     --_mono-chart-grid                    ≡ --border
     --_mono-chart-surface                 ≡ --background (the hairline between slices)
     --_mono-chart-tooltip-*               ≡ the select panel's popover: --mono-select-dropdown-{bg,color,radius,ring,shadow} → --popover … (the tooltip IS an element, painted here)
     --_mono-chart-font                    ≡ text-xs, in the page font (inherited)
     --_mono-chart-radius                  ≡ --mono-radius-md (tooltip corner, message box)
     --_mono-chart-bar-radius              ≡ the field's corner chain (--mono-input-outline-radius → --mono-input-radius → --mono-radius-md)

