.mono-chart-canvas-wrap {
  position: relative;
  width: 100%;
  /* the bar corner, in px — see the root */
  border-radius: var(--_mono-chart-bar-radius);
}
.mono-chart canvas {
  display: block;
  width: 100%;
  max-width: 100%;
}
/* The tooltip — an HTML popover placed over the canvas by the element
   (Chart.js's `tooltip.external`), not the bitmap one: a canvas can take a
   colour and a corner, not the flavour's ring and shadow. Positioned from the
   caret; `data-side` says which way it opened. */
.mono-chart-tooltip {
