  left: 0;
  top: 0;
  z-index: 2;
  display: none;
  flex-direction: column;
  gap: calc(var(--mono-spacing) * 0.5);
  /* basecoat@1.0.2 styles/vega.css .combobox [data-popover] — bg-popover text-popover-foreground ring-foreground/10 rounded-md shadow-md ring-1; px-3 py-1.5 text-xs */
  padding: calc(var(--mono-spacing) * 1.5) calc(var(--mono-spacing) * 3);
  border-radius: var(--_mono-chart-tooltip-radius);
  background: var(--_mono-chart-tooltip-bg);
  color: var(--_mono-chart-tooltip-color);
  box-shadow: var(--_mono-chart-tooltip-ring), var(--_mono-chart-tooltip-shadow);
  font-size: var(--_mono-chart-font);
  line-height: var(--mono-text-xs--lh);
  white-space: nowrap;
  pointer-events: none;
  transform: translate(-50%, calc(-100% - calc(var(--mono-spacing) * 2)));
  opacity: 0;
  transition: opacity var(--mono-duration-fast, 100ms) var(--mono-ease);
}
.mono-chart-tooltip[data-open] {
