  opacity: 1;
}
/* no room above the point: open below it */
.mono-chart-tooltip[data-side='bottom'] {
  transform: translate(-50%, calc(var(--mono-spacing) * 2));
}
.mono-chart-tooltip-title {
  font-weight: var(--mono-font-weight-medium);
}
.mono-chart-tooltip-row {
  display: flex;
  align-items: center;
  gap: calc(var(--mono-spacing) * 2);
}
/* the series swatch — a rounded chip, like the legend's */
.mono-chart-tooltip-swatch {
  flex: 0 0 auto;
  width: calc(var(--mono-spacing) * 2.5);
  height: calc(var(--mono-spacing) * 2.5);
  border-radius: var(--mono-radius-sm);
}
.mono-chart-tooltip-value {
  margin-inline-start: auto;
  font-variant-numeric: tabular-nums;
  padding-inline-start: calc(var(--mono-spacing) * 3);
