.mono-chart-message {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 6rem;
  padding: calc(var(--mono-spacing) * 4);
  font-size: var(--mono-text-sm);
  line-height: var(--mono-text-sm--lh);
  color: var(--_mono-chart-muted);
  text-align: center;
  border: var(--mono-border-width) dashed var(--_mono-chart-grid);
  border-radius: var(--_mono-chart-radius);
}
.mono-chart-message.error {
