/* =========================================
   Colours — EXTENSION: the checked fill in the role's colour
   ========================================= */
[mono-checkbox]:is(:not([mono-color]), [mono-color="primary"]) {
  --_mono-checkbox-accent-preset: var(--_mono-checkbox-primary);
  --_mono-checkbox-icon-preset: var(--_mono-checkbox-primary-foreground);
}
[mono-checkbox][mono-color="secondary"] {
  --_mono-checkbox-accent-preset: var(--secondary-foreground);
  --_mono-checkbox-icon-preset: var(--secondary);
}
[mono-checkbox][mono-color="success"] {
  --_mono-checkbox-accent-preset: var(--success);
  --_mono-checkbox-icon-preset: var(--success-foreground);
}
[mono-checkbox][mono-color="danger"] {
  --_mono-checkbox-accent-preset: var(--destructive);
  --_mono-checkbox-icon-preset: var(--destructive-foreground);
}
[mono-checkbox][mono-color="warning"] {
  --_mono-checkbox-accent-preset: var(--warning);
  --_mono-checkbox-icon-preset: var(--warning-foreground);
}
[mono-checkbox][mono-color="info"] {
  --_mono-checkbox-accent-preset: var(--info);
  --_mono-checkbox-icon-preset: var(--info-foreground);
}
[mono-checkbox][mono-color="teal"] {
  --_mono-checkbox-accent-preset: var(--teal);
  --_mono-checkbox-icon-preset: var(--teal-foreground);
}
[mono-checkbox][mono-color="purple"] {
  --_mono-checkbox-accent-preset: var(--purple);
  --_mono-checkbox-icon-preset: var(--purple-foreground);
}
[mono-checkbox][mono-color="neutral"] {
  --_mono-checkbox-accent-preset: var(--neutral);
  --_mono-checkbox-icon-preset: var(--neutral-foreground);
}
[mono-checkbox][mono-color="dark"] {
  --_mono-checkbox-accent-preset: var(--dark);
  --_mono-checkbox-icon-preset: var(--dark-foreground);
