/* =========================================
   The box
   ========================================= */
/* basecoat@1.0.2 components/checkbox.css .field > input[type='checkbox']:not([role='switch']), .input[type='checkbox']:not([role='switch'])
   — relative shrink-0 appearance-none outline-none */
/* basecoat@1.0.2 styles/vega.css .field > input[type='checkbox']:not([role='switch']), .input[type='checkbox']:not([role='switch'])
   — flex size-4 items-center justify-center rounded-[4px] border border-input
   shadow-xs transition-shadow (dark:bg-input/30 via --mono-mode-surface);
   checked:bg-primary checked:border-primary checked:text-primary-foreground;
   mono: `--tw-ring-*` flattened to the ring + shadow slots */
