  --_mono-checkbox-ring: 0 0 #0000;
  position: relative;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_mono-checkbox-control-px);
  height: var(--_mono-checkbox-control-px);
  border: var(--_mono-checkbox-border-width) solid var(--_mono-checkbox-border-color);
  border-radius: var(--_mono-checkbox-radius);
  background-color: var(--_mono-checkbox-bg);
  box-shadow: var(--_mono-checkbox-ring), var(--_mono-checkbox-shadow);
  color: var(--_mono-checkbox-icon);
  overflow: hidden;
  transition-property: box-shadow, background-color, border-color;
  transition-timing-function: var(--mono-ease);
  transition-duration: var(--mono-duration);
