  --_mono-checkbox-ring: 0 0 0 var(--_mono-checkbox-ring-width) color-mix(in oklab, var(--_mono-checkbox-ring-color) var(--_mono-checkbox-ring-alpha), transparent);
}
/* aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20
   (dark: /50, /40 via the mode tokens); aria-invalid:checked:border-primary */
[mono-checkbox][mono-invalid] > [mono-box],
:where([mono-checkbox]) > [mono-input][aria-invalid="true"] + [mono-box] {
  border-color: var(--mono-mode-invalid-border);
