:where([mono-checkbox]) > [mono-input]:is(:checked, :indeterminate) + [mono-box] {
  border-color: var(--_mono-checkbox-accent);
  background-color: var(--_mono-checkbox-accent);
  color: var(--_mono-checkbox-icon);
}
/* =========================================
   Glyphs — every glyph is out of flow (`inset: 0; margin: auto`) so the box keeps
   a stable synthesised baseline whichever one is showing
   ========================================= */
/* basecoat@1.0.2 components/checkbox.css .field > input[type='checkbox']:not([role='switch']), .input[type='checkbox']:not([role='switch'])
   — checked:after: block bg-current, mask-image var(--check-icon), mask-size 0.875rem
