  position: absolute;
  inset: 0;
  margin: auto;
  width: var(--_mono-checkbox-glyph);
  height: var(--_mono-checkbox-glyph);
  background-color: currentColor;
  pointer-events: none;
  mask-image: var(--mono-checkbox-check-icon, var(--check-icon));
  mask-repeat: no-repeat;
  mask-position: center;
  mask-size: contain;
  -webkit-mask-image: var(--mono-checkbox-check-icon, var(--check-icon));
  -webkit-mask-repeat: no-repeat;
  -webkit-mask-position: center;
  -webkit-mask-size: contain;
}
/* EXTENSION — the indeterminate dash: 60% wide, 14% tall (2px at md), pill-shaped */
:where([mono-checkbox]) > [mono-box]::after {
  content: "";
  display: none;
  position: absolute;
  inset: 0;
  margin: auto;
  width: 60%;
  height: max(1.5px, 14%);
  border-radius: 999px;
  background-color: currentColor;
  pointer-events: none;
}
[mono-checkbox][mono-checked]:not([mono-indeterminate]) > [mono-box]:not([mono-custom-icon])::before,
:where([mono-checkbox]) > [mono-input]:checked:not(:indeterminate) + [mono-box]:not([mono-custom-icon])::before {
  display: block;
}
[mono-checkbox][mono-indeterminate] > [mono-box]:not([mono-custom-indeterminate-icon])::after,
:where([mono-checkbox]) > [mono-input]:indeterminate + [mono-box]:not([mono-custom-indeterminate-icon])::after {
  display: block;
}
/* a custom glyph replaces the default one (the box is marked, or holds the wrapper) */
:where([mono-checkbox]) > [mono-box]:has([mono-icon])::before,
:where([mono-checkbox]) > [mono-box]:has([mono-indeterminate-icon])::after {
  display: none !important;
}
/* custom icon wrappers — fill the box's inner area, out of flow like the pseudo-glyphs */
:where([mono-checkbox]) [mono-icon],
:where([mono-checkbox]) [mono-indeterminate-icon] {
  display: none;
  position: absolute;
  inset: 0;
  margin: auto;
  width: 100%;
  height: 100%;
  color: var(--_mono-checkbox-icon);
  pointer-events: none;
}
:where([mono-checkbox]) [mono-icon] > *,
:where([mono-checkbox]) [mono-indeterminate-icon] > * {
  display: block;
  width: 100%;
  height: 100%;
}
[mono-checkbox][mono-checked]:not([mono-indeterminate]) [mono-icon],
:where([mono-checkbox]) > [mono-input]:checked:not(:indeterminate) + [mono-box] [mono-icon],
[mono-checkbox][mono-indeterminate] [mono-indeterminate-icon],
:where([mono-checkbox]) > [mono-input]:indeterminate + [mono-box] [mono-indeterminate-icon] {
  display: inline-block;
}
/* the shadow build projects the custom glyph through a bare <slot> */
:where([mono-checkbox]) > [mono-box] > slot[name="icon"],
:where([mono-checkbox]) > [mono-box] > slot[name="indeterminate-icon"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
:where([mono-checkbox]) > [mono-box] > slot[name="icon"]::slotted(*),
:where([mono-checkbox]) > [mono-box] > slot[name="indeterminate-icon"]::slotted(*) {
  display: block;
  width: 100%;
  height: 100%;
  color: var(--_mono-checkbox-icon);
  pointer-events: none;
}
/* =========================================
   Label
   ========================================= */
:where([mono-checkbox]) > [mono-label] {
  min-width: 0;
}
/* basecoat@1.0.2 styles/vega.css .field > label, .label — text-sm leading-snug font-medium;
   `block` so the first line box is exactly font × line-height */
:where([mono-checkbox]) [mono-label-text] {
  display: block;
  font-size: var(--_mono-checkbox-label-font);
  line-height: var(--_mono-checkbox-label-line-height);
  font-weight: var(--mono-checkbox-label-font-weight, var(--mono-label-font-weight, var(--mono-font-weight-medium)));
  color: var(--_mono-checkbox-text);
}
/* basecoat@1.0.2 styles/vega.css .fieldset legend + p, .field > p, .field section > p
   — text-sm text-muted-foreground leading-normal font-normal; EXTENSION: one step
   under the label per size */
:where([mono-checkbox]) [mono-description] {
  display: block;
  margin-top: calc(var(--mono-spacing) * 0.5);
  font-size: var(--_mono-checkbox-description-font);
  line-height: var(--mono-leading-normal);
  font-weight: var(--mono-font-weight-normal);
  color: var(--_mono-checkbox-description);
}
/* =========================================
   Loading — EXTENSION: a spinner in the box (the select-all drain of
   mono-table-checkbox and mono-tag-input). THE ONLY copy of this look: the two
   hosts emit [mono-checkbox][mono-loading] > [mono-box] > [mono-spinner] and
   restate nothing.
   ========================================= */
/* the busy box fills with the accent whatever its checked state, so the spinner
   always has the accent behind it and the icon colour in front — never white on
   white; no transition, the state may last 200ms */
[mono-checkbox][mono-loading] > [mono-box] {
  border-color: var(--_mono-checkbox-accent);
  background-color: var(--_mono-checkbox-accent);
  color: var(--_mono-checkbox-icon);
  transition: none;
}
:where([mono-checkbox]) [mono-spinner] {
  display: block;
  width: 82%;
  height: 82%;
  animation: mono-checkbox-spin 0.7s linear infinite;
}
@keyframes mono-checkbox-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  :where([mono-checkbox]) > [mono-box] {
    transition: none;
  }

  :where([mono-checkbox]) [mono-spinner] {
    animation-duration: 2.4s;
  }
}
