  position: fixed;
  z-index: calc(var(--_mono-drawer-z) + 1);
  display: flex;
  flex-direction: column;
  padding: var(--_mono-drawer-panel-pad);
  color: var(--_mono-drawer-text);
  font-size: var(--_mono-drawer-font);
  outline: none;
  pointer-events: auto;
  will-change: transform;

