    display: none;
  }
}
@media (max-width: 767.98px) {
  [mono-drawer][mono-auto-fullscreen="md"] > [mono-panel] {
    width: 100vw;
    width: 100dvw;
    height: 100vh;
    height: 100dvh;
    max-width: none;
    max-height: none;
    border-radius: 0;
  }

  [mono-drawer][mono-auto-fullscreen="md"] > [mono-panel]::before {
    border-width: 0;
    inset: 0;
  }

  [mono-drawer][mono-auto-fullscreen="md"] > [mono-panel] > [mono-resizer] {
    display: none;
  }
