@media (max-width: 1023.98px) {
  [mono-drawer][mono-auto-fullscreen="lg"] > [mono-panel] {
    width: 100vw;
    width: 100dvw;
    height: 100vh;
    height: 100dvh;
    max-width: none;
    max-height: none;
    border-radius: 0;
