    width: 100dvw;
    height: 100vh;
    height: 100dvh;
    max-width: none;
    max-height: none;
    border-radius: 0;
  }

  [mono-drawer][mono-auto-fullscreen="xl"] > [mono-panel]::before {
    border-width: 0;
