@media (max-width: 1535.98px) {
  [mono-drawer][mono-auto-fullscreen="2xl"] > [mono-panel] {
    width: 100vw;
    width: 100dvw;
    height: 100vh;
    height: 100dvh;
    max-width: none;
    max-height: none;
    border-radius: 0;
