  [mono-drawer][mono-auto-fullscreen="2xl"] > [mono-panel]::before {
    border-width: 0;
    inset: 0;
  }

  [mono-drawer][mono-auto-fullscreen="2xl"] > [mono-panel] > [mono-resizer] {
