  --_mono-dropdown-offset: var(--mono-dropdown-offset, var(--_mono-dropdown-offset-preset, var(--mono-dropdown-offset-md, var(--mono-spacing))));

  /* basecoat@1.0.2 components/popover.css .popover — relative inline-flex */
  position: relative;
  display: inline-block;
  box-sizing: border-box;
  font-family: inherit;
}
[mono-dropdown] *,
[mono-dropdown] *::before,
[mono-dropdown] *::after {
  box-sizing: border-box;
}
/* =========================================
   Sizes — EXTENSION: Basecoat ships ONE popover; md is its `[data-popover]`
   ========================================= */
[mono-dropdown][mono-size="xs"] {
  --_mono-dropdown-radius-preset: var(--mono-dropdown-radius-xs, var(--mono-radius-sm));
  --_mono-dropdown-pad-x-preset: var(--mono-dropdown-pad-x-xs, calc(var(--mono-spacing) * 2));
  --_mono-dropdown-pad-y-preset: var(--mono-dropdown-pad-y-xs, calc(var(--mono-spacing) * 2));
  --_mono-dropdown-gap-preset: var(--mono-dropdown-gap-xs, calc(var(--mono-spacing) * 1.5));
  --_mono-dropdown-font-preset: var(--mono-dropdown-font-xs, var(--mono-text-xs));
  --_mono-dropdown-line-height-preset: var(--mono-text-xs--lh);
  --_mono-dropdown-min-width-preset: var(--mono-dropdown-min-width-xs, 150px);
  --_mono-dropdown-max-width-preset: var(--mono-dropdown-max-width-xs, 220px);
  --_mono-dropdown-offset-preset: var(--mono-dropdown-offset-xs, calc(var(--mono-spacing) * 0.75));
}
[mono-dropdown][mono-size="sm"] {
  --_mono-dropdown-radius-preset: var(--mono-dropdown-radius-sm, var(--mono-radius-md));
  --_mono-dropdown-pad-x-preset: var(--mono-dropdown-pad-x-sm, calc(var(--mono-spacing) * 3));
  --_mono-dropdown-pad-y-preset: var(--mono-dropdown-pad-y-sm, calc(var(--mono-spacing) * 3));
  --_mono-dropdown-gap-preset: var(--mono-dropdown-gap-sm, calc(var(--mono-spacing) * 2.5));
  --_mono-dropdown-font-preset: var(--mono-dropdown-font-sm, var(--mono-text-xs));
  --_mono-dropdown-line-height-preset: var(--mono-text-xs--lh);
  --_mono-dropdown-min-width-preset: var(--mono-dropdown-min-width-sm, 170px);
  --_mono-dropdown-max-width-preset: var(--mono-dropdown-max-width-sm, 240px);
  --_mono-dropdown-offset-preset: var(--mono-dropdown-offset-sm, var(--mono-spacing));
}
[mono-dropdown][mono-size="lg"] {
  --_mono-dropdown-radius-preset: var(--mono-dropdown-radius-lg, var(--mono-radius-lg));
  --_mono-dropdown-pad-x-preset: var(--mono-dropdown-pad-x-lg, calc(var(--mono-spacing) * 5));
  --_mono-dropdown-pad-y-preset: var(--mono-dropdown-pad-y-lg, calc(var(--mono-spacing) * 5));
  --_mono-dropdown-gap-preset: var(--mono-dropdown-gap-lg, calc(var(--mono-spacing) * 5));
  --_mono-dropdown-font-preset: var(--mono-dropdown-font-lg, var(--mono-text-sm));
  --_mono-dropdown-line-height-preset: var(--mono-text-sm--lh);
  --_mono-dropdown-min-width-preset: var(--mono-dropdown-min-width-lg, 240px);
  --_mono-dropdown-max-width-preset: var(--mono-dropdown-max-width-lg, 340px);
  --_mono-dropdown-offset-preset: var(--mono-dropdown-offset-lg, calc(var(--mono-spacing) * 1.5));
}
[mono-dropdown][mono-size="xl"] {
  --_mono-dropdown-radius-preset: var(--mono-dropdown-radius-xl, var(--mono-radius-xl));
  --_mono-dropdown-pad-x-preset: var(--mono-dropdown-pad-x-xl, calc(var(--mono-spacing) * 6));
  --_mono-dropdown-pad-y-preset: var(--mono-dropdown-pad-y-xl, calc(var(--mono-spacing) * 6));
  --_mono-dropdown-gap-preset: var(--mono-dropdown-gap-xl, calc(var(--mono-spacing) * 5));
  --_mono-dropdown-font-preset: var(--mono-dropdown-font-xl, var(--mono-text-base));
  --_mono-dropdown-line-height-preset: var(--mono-text-base--lh);
  --_mono-dropdown-min-width-preset: var(--mono-dropdown-min-width-xl, 280px);
  --_mono-dropdown-max-width-preset: var(--mono-dropdown-max-width-xl, 420px);
  --_mono-dropdown-offset-preset: var(--mono-dropdown-offset-xl, calc(var(--mono-spacing) * 2));
}
[mono-dropdown][mono-size="xxl"] {
  --_mono-dropdown-radius-preset: var(--mono-dropdown-radius-xxl, var(--mono-radius-xl));
  --_mono-dropdown-pad-x-preset: var(--mono-dropdown-pad-x-xxl, calc(var(--mono-spacing) * 7));
  --_mono-dropdown-pad-y-preset: var(--mono-dropdown-pad-y-xxl, calc(var(--mono-spacing) * 7));
  --_mono-dropdown-gap-preset: var(--mono-dropdown-gap-xxl, calc(var(--mono-spacing) * 6));
  --_mono-dropdown-font-preset: var(--mono-dropdown-font-xxl, var(--mono-text-lg));
  --_mono-dropdown-line-height-preset: var(--mono-text-lg--lh);
  --_mono-dropdown-min-width-preset: var(--mono-dropdown-min-width-xxl, 320px);
  --_mono-dropdown-max-width-preset: var(--mono-dropdown-max-width-xxl, 480px);
  --_mono-dropdown-offset-preset: var(--mono-dropdown-offset-xxl, calc(var(--mono-spacing) * 2.5));
