[mono-dropdown][mono-color="secondary"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-secondary); }
[mono-dropdown][mono-color="success"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-success); }
[mono-dropdown][mono-color="danger"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-danger); }
[mono-dropdown][mono-color="warning"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-warning); }
[mono-dropdown][mono-color="info"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-info); }
[mono-dropdown][mono-color="teal"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-teal); }
[mono-dropdown][mono-color="purple"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-purple); }
[mono-dropdown][mono-color="neutral"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-neutral); }
[mono-dropdown][mono-color="dark"] { --_mono-dropdown-accent-preset: var(--_mono-dropdown-dark); }
/* =========================================
   Activator — EXTENSION: a wrapper that stays out of layout
   ========================================= */
:where([mono-dropdown]) > [mono-activator] {
  display: contents;
}
/* The activator is the consumer's own control, so it is dimmed once and gently:
   0.55 is the pre-port value, kept so a disabled dropdown reads the same. */
