[mono-dropdown]:not([mono-side]) > [mono-panel][aria-hidden="true"],
[mono-dropdown][mono-side="bottom"] > [mono-panel][aria-hidden="true"] {
  translate: 0 calc(var(--mono-spacing) * -2);
}
[mono-dropdown][mono-side="left"] > [mono-panel][aria-hidden="true"] {
  translate: calc(var(--mono-spacing) * 2) 0;
}
[mono-dropdown][mono-side="right"] > [mono-panel][aria-hidden="true"] {
  translate: calc(var(--mono-spacing) * -2) 0;
}
