   — mt-1 top-full */
[mono-dropdown]:not([mono-side]):not([mono-fixed]) > [mono-panel],
[mono-dropdown][mono-side="bottom"]:not([mono-fixed]) > [mono-panel] {
  top: 100%;
  margin-top: var(--_mono-dropdown-offset);
}
/* basecoat@1.0.2 components/popover.css [data-popover] >> &[data-side='top'] — mb-1 bottom-full */
[mono-dropdown][mono-side="top"]:not([mono-fixed]) > [mono-panel] {
  bottom: 100%;
  margin-bottom: var(--_mono-dropdown-offset);
}
/* basecoat@1.0.2 components/popover.css [data-popover] >> &[data-side='left'] — me-1 end-full */
[mono-dropdown][mono-side="left"]:not([mono-fixed]) > [mono-panel] {
  inset-inline-end: 100%;
  margin-inline-end: var(--_mono-dropdown-offset);
}
/* basecoat@1.0.2 components/popover.css [data-popover] >> &[data-side='right'] — ms-1 start-full */
[mono-dropdown][mono-side="right"]:not([mono-fixed]) > [mono-panel] {
  inset-inline-start: 100%;
  margin-inline-start: var(--_mono-dropdown-offset);
}
/* The top/bottom pair aligns on the inline axis: start-0 / end-0 / start-1/2 -translate-x-1/2 */
[mono-dropdown]:is(:not([mono-side]), [mono-side="top"], [mono-side="bottom"]):is(:not([mono-align]), [mono-align="start"]):not([mono-fixed]) > [mono-panel] {
  inset-inline-start: 0;
}
[mono-dropdown]:is(:not([mono-side]), [mono-side="top"], [mono-side="bottom"])[mono-align="end"]:not([mono-fixed]) > [mono-panel] {
  inset-inline-end: 0;
}
[mono-dropdown]:is(:not([mono-side]), [mono-side="top"], [mono-side="bottom"])[mono-align="center"]:not([mono-fixed]) > [mono-panel] {
  inset-inline-start: 50%;
  translate: -50% 0;
