/* …and the left/right pair on the block axis: top-0 / bottom-0 / top-1/2 -translate-y-1/2 */
[mono-dropdown]:is([mono-side="left"], [mono-side="right"]):is(:not([mono-align]), [mono-align="start"]):not([mono-fixed]) > [mono-panel] {
  top: 0;
}
[mono-dropdown]:is([mono-side="left"], [mono-side="right"])[mono-align="end"]:not([mono-fixed]) > [mono-panel] {
  bottom: 0;
}
[mono-dropdown]:is([mono-side="left"], [mono-side="right"])[mono-align="center"]:not([mono-fixed]) > [mono-panel] {
  top: 50%;
  translate: 0 -50%;
