  font-size: var(--mono-file-upload-subtext-font-size, var(--mono-text-sm));
  line-height: var(--mono-file-upload-subtext-line-height, var(--mono-leading-relaxed));
  color: var(--mono-file-upload-subtext-color, var(--_mono-file-upload-muted));
