/* basecoat@1.0.2 components/item.css .item — flex w-full flex-wrap items-center
   border transition-colors duration-100 outline-none;
   styles/vega.css .item — rounded-md border text-sm;
   styles/vega.css .item[data-variant='outline'] — border-border;
   styles/vega.css .item[data-size='sm'] — gap-2.5 px-3 py-2.5 */
