  width: 100%;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--_mono-file-upload-item-gap);
  padding-inline: var(--_mono-file-upload-item-padding-x);
  padding-block: var(--_mono-file-upload-item-padding-y);
  border: var(--_mono-file-upload-item-border-width) solid var(--_mono-file-upload-item-border-color);
  border-radius: var(--_mono-file-upload-item-radius);
  background-color: var(--_mono-file-upload-item-bg);
