/* basecoat@1.0.2 styles/vega.css .item[data-size='sm'] > figure:has(> img) — size-8;
   styles/vega.css .item > figure:has(> img) — overflow-hidden rounded-sm;
   components/item.css .item > figure:has(> img) — [&_img]:size-full [&_img]:object-cover;
   styles/vega.css .item > figure:has(> svg:only-child) — a size-4 glyph */
