  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: var(--_mono-file-upload-thumb-size);
  height: var(--_mono-file-upload-thumb-size);
  overflow: hidden;
  border-radius: var(--_mono-file-upload-thumb-radius);
  background-color: var(--_mono-file-upload-thumb-bg);
