  height: calc(var(--mono-spacing) * 4);
  flex-shrink: 0;
}
:where([mono-file-upload]) [mono-thumb] [mono-glyph] > svg {
  width: 100%;
  height: 100%;
}
/* basecoat@1.0.2 components/item.css .item > section — flex flex-1 flex-col;
   styles/vega.css .item > section — gap-1 (gap-0 at data-size='xs') */
:where([mono-file-upload]) [mono-file] {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
  flex-direction: column;
  gap: var(--_mono-file-upload-file-gap);
}
/* basecoat@1.0.2 components/item.css .item :is(h2, h3, h4) — line-clamp-1 flex
   w-fit items-center;
   styles/vega.css .item :is(h2, h3, h4) — text-sm leading-snug font-medium
