  max-width: 100%;
  font-size: var(--mono-file-upload-name-font-size, var(--mono-text-sm));
  line-height: var(--mono-file-upload-name-line-height, var(--mono-leading-snug));
  font-weight: var(--mono-file-upload-name-font-weight, var(--mono-font-weight-medium));
  color: var(--_mono-file-upload-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
