/* basecoat@1.0.2 components/item.css .item p — text-muted-foreground line-clamp-2
   text-start font-normal;
   styles/vega.css .item p — text-sm leading-normal (text-xs at data-size='xs') */
:where([mono-file-upload]) [mono-meta] {
  font-size: var(--_mono-file-upload-meta-font-size);
  line-height: var(--mono-file-upload-meta-line-height, var(--mono-leading-normal));
  font-weight: var(--mono-font-weight-normal);
  text-align: start;
  color: var(--mono-file-upload-meta-color, var(--_mono-file-upload-muted));
}
/* basecoat@1.0.2 styles/vega.css .btn[data-variant='ghost'] — hover:bg-muted
   hover:text-foreground (dark:hover:bg-muted/50);
   styles/vega.css .btn[data-size='icon-sm'] — size-8 rounded-[min(var(--radius-md),10px)]
   — DEVIATION: the hover ink is the DANGER role, not `--foreground`: this ghost
   button deletes the row it sits in. */
:where([mono-file-upload]) [mono-remove] {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: var(--mono-file-upload-remove-size, calc(var(--mono-spacing) * 8));
  height: var(--mono-file-upload-remove-size, calc(var(--mono-spacing) * 8));
  padding: 0;
  border: 0;
  border-radius: var(--mono-file-upload-remove-radius, min(var(--mono-radius-md), 10px));
  background: transparent;
  color: var(--_mono-file-upload-muted);
