:where([mono-file-upload]) [mono-remove] [mono-glyph] {
  display: block;
  width: calc(var(--mono-spacing) * 4);
  height: calc(var(--mono-spacing) * 4);
  flex-shrink: 0;
  color: inherit;
}
:where([mono-file-upload]) [mono-remove] [mono-glyph] > svg {
  width: 100%;
  height: 100%;
}
[mono-file-upload][mono-disabled] [mono-remove] {
  opacity: 0.5;
  pointer-events: none;
}
/* =========================================
   Message
   ========================================= */
/* basecoat@1.0.2 styles/vega.css .fieldset legend + p, .field > p, .field section > p
   — text-sm text-muted-foreground leading-normal font-normal */
:where([mono-file-upload]) [mono-message] {
  font-size: var(--mono-file-upload-message-font-size, var(--mono-text-sm));
  line-height: var(--mono-file-upload-message-line-height, var(--mono-leading-normal));
  color: var(--mono-file-upload-message-color, var(--_mono-file-upload-muted));
}
/* basecoat@1.0.2 components/field.css .field >> [role='alert'] — the invalid message
