  --_mono-input-padding-x: var(--mono-input-padding-x-xs, var(--_mono-input-padding-x-preset, calc(var(--mono-spacing) * 2)));
  --_mono-input-font-size: var(--mono-input-font-xs, var(--mono-text-xs));
  --_mono-input-line-height: var(--mono-input-line-height, var(--mono-input-line-height-xs, var(--mono-text-xs--lh)));
  --_mono-input-affix-icon: var(--mono-input-affix-icon-size, calc(var(--mono-spacing) * 3.5));
  --_mono-input-clear: calc(var(--mono-spacing) * 4);
  --_mono-input-clear-glyph: calc(var(--mono-spacing) * 3);
