  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  padding-inline-start: var(--_mono-date-affix-padding);
  color: var(--_mono-date-muted);
  user-select: none;
  pointer-events: none;
}
[mono-date] [mono-prefix] > :is(svg, .mono-icon, [mono-icon]) {
  display: block;
  width: var(--_mono-date-affix-icon);
  height: var(--_mono-date-affix-icon);
  flex-shrink: 0;
