   caption text-sm font-medium, weekdays text-muted-foreground text-[0.8rem].
   ========================================= */
.flatpickr-calendar.mono-flatpickr {
  --cal-bg: var(--mono-date-calendar-bg, var(--popover));
  --cal-text: var(--mono-date-calendar-color, var(--popover-foreground));
  --cal-muted: var(--muted-foreground);
  --cal-faint: color-mix(in oklab, var(--muted-foreground) 50%, transparent);
  --cal-border: var(--border);
  --cal-soft: var(--accent);
  --cal-soft-foreground: var(--accent-foreground);
  --cal-accent: var(--primary);
  --cal-accent-foreground: var(--primary-foreground);
  --cal-radius: var(--mono-date-calendar-day-radius, var(--mono-radius-md));

  background: var(--cal-bg);
  border: 0;
  border-radius: var(--mono-date-calendar-radius, var(--mono-radius-md));
  box-shadow: var(--mono-date-calendar-ring, 0 0 0 1px color-mix(in oklab, var(--foreground) 10%, transparent)), var(--mono-date-calendar-shadow, var(--mono-shadow-md));
  color: var(--cal-text);
  font-family: inherit;
  font-size: var(--mono-text-sm);
  line-height: var(--mono-text-sm--lh);
}
/* a popover has no pointer arrow */
.flatpickr-calendar.mono-flatpickr::before,
.flatpickr-calendar.mono-flatpickr::after {
  display: none;
}
/* months / header — text-sm font-medium */
.flatpickr-calendar.mono-flatpickr .flatpickr-month,
.flatpickr-calendar.mono-flatpickr .flatpickr-current-month,
.flatpickr-calendar.mono-flatpickr .flatpickr-current-month input.cur-year {
  color: var(--cal-text);
  fill: var(--cal-text);
  font-size: var(--mono-text-sm);
  font-weight: var(--mono-font-weight-medium);
}
/* nav — .btn[data-variant='outline'][data-size='icon-sm']: size-7 rounded-md
   border-border bg-background hover:bg-muted, painted flat here */
.flatpickr-calendar.mono-flatpickr .flatpickr-prev-month,
.flatpickr-calendar.mono-flatpickr .flatpickr-next-month {
  color: var(--cal-muted);
  fill: var(--cal-muted);
  border-radius: var(--cal-radius);
  transition-property: color, background-color;
  transition-timing-function: var(--mono-ease);
  transition-duration: var(--mono-duration);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-prev-month svg,
.flatpickr-calendar.mono-flatpickr .flatpickr-next-month svg {
  fill: currentColor;
}
.flatpickr-calendar.mono-flatpickr .flatpickr-prev-month:hover,
.flatpickr-calendar.mono-flatpickr .flatpickr-next-month:hover {
  background: var(--cal-soft);
  color: var(--cal-soft-foreground);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-prev-month:hover svg,
.flatpickr-calendar.mono-flatpickr .flatpickr-next-month:hover svg {
  fill: var(--cal-soft-foreground);
}
/* month dropdown — a native <select>. Its popup list is drawn by the browser
