   select falls back to the OS palette, which is what mismatched the dark popover),
   so the select carries the popover surface and never changes it on hover. */
.flatpickr-calendar.mono-flatpickr .flatpickr-monthDropdown-months {
  background: var(--cal-bg);
  color: var(--cal-text);
  color-scheme: inherit;
  font-weight: var(--mono-font-weight-medium);
  border-radius: var(--cal-radius);
  transition-property: color;
  transition-timing-function: var(--mono-ease);
  transition-duration: var(--mono-duration);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-monthDropdown-months:hover {
  background: var(--cal-bg);
  color: var(--cal-accent);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-monthDropdown-months .flatpickr-monthDropdown-month {
  background: var(--cal-bg);
  color: var(--cal-text);
  font-weight: var(--mono-font-weight-normal);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-monthDropdown-months .flatpickr-monthDropdown-month:checked {
  background: var(--cal-soft);
  color: var(--cal-soft-foreground);
}
/* year stepper */
.flatpickr-calendar.mono-flatpickr .numInputWrapper:hover {
  background: var(--cal-soft);
}
.flatpickr-calendar.mono-flatpickr .numInputWrapper span {
  border-color: var(--cal-border);
}
.flatpickr-calendar.mono-flatpickr .numInputWrapper span:hover {
  background: var(--cal-soft);
}
.flatpickr-calendar.mono-flatpickr .numInputWrapper span.arrowUp::after {
  border-bottom-color: var(--cal-muted);
}
.flatpickr-calendar.mono-flatpickr .numInputWrapper span.arrowDown::after {
  border-top-color: var(--cal-muted);
}
/* weekdays — text-muted-foreground text-[0.8rem] font-normal */
.flatpickr-calendar.mono-flatpickr .flatpickr-weekdays {
  background: transparent;
}
.flatpickr-calendar.mono-flatpickr span.flatpickr-weekday {
  background: transparent;
  color: var(--cal-muted);
  font-size: 0.8rem;
  font-weight: var(--mono-font-weight-normal);
}
/* days — rounded-md text-sm; hover bg-accent; today bg-accent; selected bg-primary */
.flatpickr-calendar.mono-flatpickr .flatpickr-day {
  color: var(--cal-text);
  border: 1px solid transparent;
  border-radius: var(--cal-radius);
  font-size: var(--mono-text-sm);
  font-weight: var(--mono-font-weight-normal);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-day:hover,
.flatpickr-calendar.mono-flatpickr .flatpickr-day:focus {
  background: var(--cal-soft);
  border-color: transparent;
  color: var(--cal-soft-foreground);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-day.today {
  background: var(--cal-soft);
  border-color: transparent;
  color: var(--cal-soft-foreground);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-day.selected,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.startRange,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.endRange,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.selected:hover,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.startRange:hover,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.endRange:hover,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.selected:focus,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.startRange:focus,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.endRange:focus,
.flatpickr-calendar.mono-flatpickr .flatpickr-day.selected.today {
  background: var(--cal-accent);
  border-color: var(--cal-accent);
  color: var(--cal-accent-foreground);
}
/* range middle — bg-accent, squared between the two ends */
.flatpickr-calendar.mono-flatpickr .flatpickr-day.inRange {
  background: var(--cal-soft);
  border-color: transparent;
  color: var(--cal-soft-foreground);
  border-radius: 0;
  box-shadow: -5px 0 0 var(--cal-soft), 5px 0 0 var(--cal-soft);
