/* week numbers */
.flatpickr-calendar.mono-flatpickr .flatpickr-weekwrapper .flatpickr-weekday,
.flatpickr-calendar.mono-flatpickr .flatpickr-weekwrapper span.flatpickr-day {
  color: var(--cal-faint);
}
/* time */
.flatpickr-calendar.mono-flatpickr.hasTime .flatpickr-time {
  border-top: 1px solid var(--cal-border);
}
.flatpickr-calendar.mono-flatpickr .flatpickr-time input,
.flatpickr-calendar.mono-flatpickr .flatpickr-time .flatpickr-time-separator,
.flatpickr-calendar.mono-flatpickr .flatpickr-time .flatpickr-am-pm {
  color: var(--cal-text);
  background: transparent;
}
.flatpickr-calendar.mono-flatpickr .flatpickr-time input:hover,
.flatpickr-calendar.mono-flatpickr .flatpickr-time input:focus,
.flatpickr-calendar.mono-flatpickr .flatpickr-time .flatpickr-am-pm:hover,
.flatpickr-calendar.mono-flatpickr .flatpickr-time .flatpickr-am-pm:focus {
  background: var(--cal-soft);
  color: var(--cal-soft-foreground);
}
/* the inline calendar (`inline`) sits in the page flow, on the field's own surface */
.flatpickr-calendar.mono-flatpickr.inline {
  box-shadow: var(--mono-date-calendar-ring, 0 0 0 1px color-mix(in oklab, var(--foreground) 10%, transparent));
