  --_mono-radio-control: var(--mono-radio-size-xs, calc(var(--mono-control-height-xs) * 4 / 9));
  --_mono-radio-gap: var(--mono-radio-gap, var(--mono-radio-gap-xs, calc(var(--mono-spacing) * 1.25)));
  --_mono-radio-label-font: var(--mono-radio-label-font-xs, var(--mono-text-xs));
  --_mono-radio-description-font: var(--mono-radio-description-font-xs, 0.6875rem);
}
[mono-radio][mono-size="sm"] {
  --_mono-radio-control: var(--mono-radio-size-sm, calc(var(--mono-control-height-sm) * 4 / 9));
  --_mono-radio-gap: var(--mono-radio-gap, var(--mono-radio-gap-sm, calc(var(--mono-spacing) * 1.5)));
  --_mono-radio-label-font: var(--mono-radio-label-font-sm, 0.8125rem);
  --_mono-radio-description-font: var(--mono-radio-description-font-sm, var(--mono-text-xs));
}
[mono-radio][mono-size="lg"] {
  --_mono-radio-control: var(--mono-radio-size-lg, calc(var(--mono-control-height-lg) * 4 / 9));
  --_mono-radio-gap: var(--mono-radio-gap, var(--mono-radio-gap-lg, calc(var(--mono-spacing) * 2.5)));
  --_mono-radio-label-font: var(--mono-radio-label-font-lg, var(--mono-text-base));
  --_mono-radio-description-font: var(--mono-radio-description-font-lg, var(--mono-text-sm));
  /* 16px text rounds its ascent such that the circle lands ~0.35px low */
  --_mono-radio-optical-nudge: -0.35px;
}
[mono-radio][mono-size="xl"] {
  --_mono-radio-control: var(--mono-radio-size-xl, calc(var(--mono-control-height-xl) * 4 / 9));
  --_mono-radio-gap: var(--mono-radio-gap, var(--mono-radio-gap-xl, calc(var(--mono-spacing) * 3)));
  --_mono-radio-label-font: var(--mono-radio-label-font-xl, var(--mono-text-lg));
  --_mono-radio-description-font: var(--mono-radio-description-font-xl, var(--mono-text-base));
}
[mono-radio][mono-size="xxl"] {
  --_mono-radio-control: var(--mono-radio-size-xxl, calc(var(--mono-control-height-xxl) * 4 / 9));
  --_mono-radio-gap: var(--mono-radio-gap, var(--mono-radio-gap-xxl, calc(var(--mono-spacing) * 3.5)));
  --_mono-radio-label-font: var(--mono-radio-label-font-xxl, var(--mono-text-xl));
  --_mono-radio-description-font: var(--mono-radio-description-font-xxl, var(--mono-text-lg));
  /* 20px text rounds the other way, leaving the circle ~1.1px high */
  --_mono-radio-optical-nudge: 1.1px;
