/* =========================================
   Colours — EXTENSION: the checked fill in the role's colour
   ========================================= */
[mono-radio]:is(:not([mono-color]), [mono-color="primary"]) {
  --_mono-radio-accent-preset: var(--_mono-radio-primary);
  --_mono-radio-dot-preset: var(--_mono-radio-primary-foreground);
}
[mono-radio][mono-color="secondary"] {
  --_mono-radio-accent-preset: var(--secondary-foreground);
  --_mono-radio-dot-preset: var(--secondary);
}
[mono-radio][mono-color="success"] {
  --_mono-radio-accent-preset: var(--success);
  --_mono-radio-dot-preset: var(--success-foreground);
}
[mono-radio][mono-color="danger"] {
  --_mono-radio-accent-preset: var(--destructive);
  --_mono-radio-dot-preset: var(--destructive-foreground);
}
[mono-radio][mono-color="warning"] {
  --_mono-radio-accent-preset: var(--warning);
  --_mono-radio-dot-preset: var(--warning-foreground);
}
[mono-radio][mono-color="info"] {
  --_mono-radio-accent-preset: var(--info);
  --_mono-radio-dot-preset: var(--info-foreground);
}
[mono-radio][mono-color="teal"] {
  --_mono-radio-accent-preset: var(--teal);
  --_mono-radio-dot-preset: var(--teal-foreground);
}
[mono-radio][mono-color="purple"] {
  --_mono-radio-accent-preset: var(--purple);
  --_mono-radio-dot-preset: var(--purple-foreground);
}
[mono-radio][mono-color="neutral"] {
  --_mono-radio-accent-preset: var(--neutral);
  --_mono-radio-dot-preset: var(--neutral-foreground);
}
[mono-radio][mono-color="dark"] {
  --_mono-radio-accent-preset: var(--dark);
  --_mono-radio-dot-preset: var(--dark-foreground);
}
/* =========================================
   States on the root
   ========================================= */
/* basecoat@1.0.2 components/radio.css .field > input[type='radio'], .input[type='radio']
   — disabled:cursor-not-allowed disabled:opacity-50 */
[mono-radio][mono-disabled],
[mono-radio]:has(> [mono-input]:disabled) {
  cursor: not-allowed;
  opacity: 0.5;
  pointer-events: none;
}
/* the native input is the accessible control; the circle is its painted twin */
:where([mono-radio]) [mono-input] {
  position: absolute;
  opacity: 0;
  pointer-events: none;
  width: 1px;
  height: 1px;
  margin: 0;
  /* the UA gives an <input> its own font; inside a shadow root nothing resets it,
     so the hidden control ended up with a different computed font in the two
     builds. It paints nothing either way — this just keeps them identical. */
  font: inherit;
  color: inherit;
}
/* =========================================
   The circle
   ========================================= */
/* basecoat@1.0.2 components/radio.css .field > input[type='radio'], .input[type='radio']
   — relative shrink-0 appearance-none border outline-none */
/* basecoat@1.0.2 styles/vega.css .field > input[type='radio'], .input[type='radio']
   — flex size-4 rounded-full border-input (dark:bg-input/30 via --mono-mode-surface);
   checked:bg-primary checked:border-primary checked:text-primary-foreground;
   mono: `--tw-ring-*` flattened to the ring + shadow slots */
:where([mono-radio]) > [mono-circle] {
  --_mono-radio-ring: 0 0 #0000;
  position: relative;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_mono-radio-control-px);
  height: var(--_mono-radio-control-px);
  border: var(--_mono-radio-border-width) solid var(--_mono-radio-border-color);
  border-radius: var(--_mono-radio-radius);
  background-color: var(--_mono-radio-bg);
  box-shadow: var(--_mono-radio-ring), var(--_mono-radio-shadow);
  /* the circle's own ink is the ACCENT — a flavor that leaves the checked circle
     hollow (sera) then sets `--mono-radio-dot-color: currentColor` to paint the
     dot in the role colour, using public knobs alone */
  color: var(--_mono-radio-accent);
  transition-property: box-shadow, background-color, border-color;
  transition-timing-function: var(--mono-ease);
  transition-duration: var(--mono-duration);
}
/* focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 */
:where([mono-radio]) > [mono-input]:focus-visible + [mono-circle] {
  border-color: var(--_mono-radio-ring-color);
  --_mono-radio-ring: 0 0 0 var(--_mono-radio-ring-width) color-mix(in oklab, var(--_mono-radio-ring-color) var(--_mono-radio-ring-alpha), transparent);
}
/* aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20
   (dark: /50, /40 via the mode tokens) */
[mono-radio][mono-invalid] > [mono-circle],
:where([mono-radio]) > [mono-input][aria-invalid="true"] + [mono-circle] {
  border-color: var(--mono-mode-invalid-border);
  --_mono-radio-ring: 0 0 0 var(--_mono-radio-ring-width) var(--mono-mode-invalid-ring);
}
/* checked:bg-primary checked:border-primary — generalised per hue.
   `--mono-radio-checked-bg` is the flavor slot: sera keeps the circle hollow. */
[mono-radio][mono-checked] > [mono-circle],
:where([mono-radio]) > [mono-input]:checked + [mono-circle] {
  border-color: var(--_mono-radio-accent);
  background-color: var(--mono-radio-checked-bg, var(--_mono-radio-accent));
}
/* aria-invalid:checked:border-primary — a chosen option is not the error */
[mono-radio][mono-invalid][mono-checked] > [mono-circle],
:where([mono-radio]) > [mono-input][aria-invalid="true"]:checked + [mono-circle] {
  border-color: var(--_mono-radio-accent);
}
/* =========================================
   The dot — `:checked:before` upstream. The element renders [mono-dot] (it is a
   `cssClass` slot); hand-written markup may leave the circle empty and take the
   pseudo-element instead. Both are out of flow (`inset: 0; margin: auto`) so the
   circle keeps a stable synthesised baseline.
   ========================================= */
/* basecoat@1.0.2 components/radio.css .field > input[type='radio'], .input[type='radio'] >> &:checked:before
   — absolute top-1/2 left-1/2 content-[''] -translate-x/y-1/2 rounded-full */
/* basecoat@1.0.2 styles/vega.css :is(.field > input[type='radio'], .input[type='radio']):checked:before
   — size-2 bg-primary-foreground (mono: that share of the box, so it tracks every step) */
