    var(--_mono-switch-thumb-h-px) + 2 * var(--_mono-switch-border-width) + 2 * var(--_mono-switch-thumb-inset-y)
  );
  --_mono-switch-track-w-px: round(nearest, var(--_mono-switch-track-w), 1px);
  --_mono-switch-travel-px: calc(
