     <mono-tabs size="lg" color="success" variant="pill" model-value="a">
     <div mono-tabs mono-size="lg" mono-color="success" mono-variant="pill"
          role="tablist" aria-orientation="horizontal">
       <button mono-tab type="button" role="tab" aria-selected="true">
         <span mono-icon>…</span>
         <span mono-label>Overview</span>
         <span mono-badge>3</span>
       </button>
     </div>

