[mono-tag-input] [mono-chip][mono-chip-color="warning"] > [mono-chip-main] { background: color-mix(in oklab, var(--warning) var(--mono-mode-tint), transparent); color: var(--warning); }
[mono-tag-input] [mono-chip][mono-chip-color="info"] > [mono-chip-main] { background: color-mix(in oklab, var(--info) var(--mono-mode-tint), transparent); color: var(--info); }
[mono-tag-input] [mono-chip][mono-chip-color="teal"] > [mono-chip-main] { background: color-mix(in oklab, var(--teal) var(--mono-mode-tint), transparent); color: var(--teal); }
[mono-tag-input] [mono-chip][mono-chip-color="purple"] > [mono-chip-main] { background: color-mix(in oklab, var(--purple) var(--mono-mode-tint), transparent); color: var(--purple); }
[mono-tag-input] [mono-chip][mono-chip-color="neutral"] > [mono-chip-main] { background: color-mix(in oklab, var(--neutral) var(--mono-mode-tint), transparent); color: var(--neutral); }
