  --_se-radius: var(--mono-radius-sm);
  --_se-radius-lg: var(--_mono-rte-popover-radius);
  --_se-shadow-layer: var(--_mono-rte-popover-shadow);
  --_se-font-family: var(--_mono-rte-font-family);
  --_se-font-size: var(--_mono-rte-font-size);
  --_se-icon-size: var(--_mono-rte-icon-size);
