  --se-main-color-lighter: var(--_se-main-color-lighter);
  --se-main-font-color: var(--_se-main-color);
  --se-main-background-color: var(--_se-main-background);
  --se-main-border-color: var(--_se-main-border);
  --se-main-divider-color: var(--_se-main-divider);
  --se-main-outline-color: var(--_se-main-outline);
